const root = process.cwd();
const inputPath = path.join(root, '.diagnostic-questions', 'visual-jobs-current.json');
const outputDir = path.join(root, '.diagnostic-questions', 'transcriptions-full-20260802');

const t = {
  '20816': {question_text:'Votes in a local election were surveyed and classified by age group and party preference. The observed frequencies are $\begin{array}{c|ccc|c}\text{}&\text{Blue}&\text{Red}&\text{Green}&\text{Total}\\\hline18\text{--}30&12&6&17&35\\31\text{--}45&22&18&10&50\\45\text{--}60&16&10&9&35\\60+&19&4&7&30\\\hline\text{Total}&69&38&43&150\end{array}$. A $\chi^2$-test is to be carried out. Find the expected number of 18--30 year olds who will vote for the Green Party.',structure:'find-expected-frequency-from-row-and-column-totals',meaningfulCase:'expected-count-from-independent-row-and-column-margins',mastery:false,options:[{text:'$10$',correct:true},{text:'$11$',correct:false,why:'Uses an inaccurate rounded estimate instead of the expected-frequency calculation.'},{text:'$16$',correct:false,why:'Confuses an observed frequency from a different table cell with an expected frequency.'},{text:'$17$',correct:false,why:'Repeats the observed Green count instead of calculating the expected count.'}],solution_text:'For independence, the expected frequency is $\dfrac{(\text{row total})(\text{column total})}{\text{grand total}}$. Thus $E=\dfrac{35\times43}{150}=10.033\ldots$, which is $10$ to the nearest whole number.',diagramRequired:false,uncertainties:[]},
  '2115': {question_text:'Which of these shapes is correctly reflected in the mirror line?',structure:'reflect-shape-in-diagonal-mirror-line',meaningfulCase:'reflection-in-line-with-slope-negative-one',mastery:false,options:[{text:'Green',correct:true},{text:'Black',correct:false,why:'The black triangle does not have the corresponding reflected vertex distances.'},{text:'Red',correct:false,why:'The red triangle has the wrong orientation and position after reflection.'},{text:'Purple',correct:false,why:'The purple triangle is not at matching perpendicular distances from the mirror.'}],solution_text:'A reflection preserves size and reverses the orientation of the shape. Checking the perpendicular distances of the vertices from the diagonal mirror line shows that the green triangle is the correct image.',diagramRequired:true,uncertainties:['The grid diagram has no explicit coordinate labels, so the TikZ reconstruction is schematic.']},
  '21865': {question_text:'The formula $e=\dfrac{u}{v}$ should be used\ldots',structure:'identify-coefficient-of-restitution-context',meaningfulCase:'coefficient-of-restitution-for-particle-collision',mastery:false,options:[{text:'when 2 particles collide',correct:true},{text:'when a particle collides with a wall',correct:false,why:'This is not the stated two-particle collision context for the formula.'},{text:'to find the impact',correct:false,why:'The formula relates speeds before and after collision, not impact as a general quantity.'},{text:'none of the above',correct:false,why:'The first option gives the standard collision context for the formula.'}],solution_text:'The coefficient of restitution is defined using the relative speed of separation and the relative speed of approach for two colliding particles. Therefore the formula is used when two particles collide.',diagramRequired:false,uncertainties:[]},
  '2872': {question_text:'For the following random variables, state which one can be modelled by a binomial distribution:\n\nA: A dice is thrown repeatedly until a three is seen. $X=$ number of throws.\n\nB: A bag has 12 blue marbles and 6 red marbles. Five marbles are selected without replacement. $X=$ number of red marbles.\n\nC: A pair of dice are thrown 14 times. $X=$ average score of the sum of the numbers showing.\n\nD: $X=$ number of boys in a family of 6 children.',structure:'identify-binomial-random-variable',meaningfulCase:'fixed-number-of-independent-bernoulli-trials',mastery:false,options:[{text:'A',correct:false,why:'The number of trials is random because throwing stops when a three appears.'},{text:'B',correct:false,why:'Sampling without replacement changes the success probability between draws.'},{text:'C',correct:false,why:'An average of dice sums is not a count of Bernoulli successes.'},{text:'D',correct:true}],solution_text:'A binomial variable counts successes in a fixed number of independent trials with a constant success probability. The number of boys in six children satisfies this model, so $X\sim\operatorname{Bin}(6,p)$ (with the usual independence assumption).',diagramRequired:false,uncertainties:[]},
  '3036': {question_text:'Describe the transformation from $y=f(x)$ to $y=f(x+6)$.',structure:'describe-horizontal-translation-from-function-argument',meaningfulCase:'positive-inside-shift-moves-graph-left',mastery:false,options:[{text:'Translation by the vector $\begin{pmatrix}0\\-6\end{pmatrix}$',correct:false,why:'This is a vertical translation and changes the output rather than the input.'},{text:'Translation by the vector $\begin{pmatrix}-6\\0\end{pmatrix}$',correct:true},{text:'Translation by the vector $\begin{pmatrix}0\\6\end{pmatrix}$',correct:false,why:'This is a vertical translation, whereas the change is inside the function argument.'},{text:'Translation by the vector $\begin{pmatrix}6\\0\end{pmatrix}$',correct:false,why:'A positive horizontal shift would correspond to $f(x-6)$, not $f(x+6)$.'}],solution_text:'Replacing $x$ by $x+6$ moves every point six units to the left. Hence the translation vector is $\begin{pmatrix}-6\\0\end{pmatrix}$.',diagramRequired:false,uncertainties:[]},
  '15073': {question_text:'What is the gradient of the line joining points $(-2,4)$ and $(4,9)$?',structure:'calculate-gradient-between-two-points',meaningfulCase:'positive-gradient-from-coordinate-differences',mastery:false,options:[{text:'$\dfrac52$',correct:false,why:'Reverses the coordinate differences and uses the reciprocal gradient.'},{text:'$\dfrac65$',correct:false,why:'Uses the horizontal difference over the vertical difference.'},{text:'$\dfrac56$',correct:true},{text:'$\dfrac25$',correct:false,why:'Uses the reciprocal of the correct rise divided by run.'}],solution_text:'The gradient is rise divided by run: $m=\dfrac{9-4}{4-(-2)}=\dfrac{5}{6}$.',diagramRequired:false,uncertainties:[]},
  '1977': {question_text:'An electrician charges a £30 call-out charge plus £20 an hour. What formula works out the cost $C$ for $n$ hours\' work?',structure:'formulate-linear-cost-with-fixed-charge',meaningfulCase:'fixed-charge-plus-constant-rate',mastery:false,options:[{text:'$AC=20+30n$',correct:false,why:'Introduces an undefined extra variable and reverses the role of the hourly charge.'},{text:'$C=50n$',correct:false,why:'Multiplies the fixed charge by the number of hours instead of adding it once.'},{text:'$C=30+20n$',correct:true},{text:'$C=50+n$',correct:false,why:'Adds the two charges and uses only one unit per hour.'}],solution_text:'The fixed call-out charge is £30 and the variable charge is £20 for each of $n$ hours. Therefore $C=30+20n$.',diagramRequired:false,uncertainties:[]},
  '20832': {question_text:'Votes in a local election were surveyed and classified by age group and party preference. The observed frequencies are $\begin{array}{c|ccc|c}\text{}&\text{Blue}&\text{Red}&\text{Green}&\text{Total}\\\hline18\text{--}30&12&6&17&35\\31\text{--}45&22&18&10&50\\45\text{--}60&16&10&9&35\\60+&19&4&7&30\\\hline\text{Total}&69&38&43&150\end{array}$. A $\chi^2$-test is to be carried out at the $1\%$ level of significance. Calculate the $p$-value.',structure:'calculate-chi-square-test-p-value-from-contingency-table',meaningfulCase:'independence-test-with-six-degrees-of-freedom',mastery:false,options:[{text:'$0.01$',correct:false,why:'This is the chosen significance level, not the calculated p-value.'},{text:'$0.05$',correct:false,why:'Confuses a common significance level with the p-value for this table.'},{text:'$0.023$',correct:true},{text:'$0.99$',correct:false,why:'Uses the complement of the significance level rather than the test result.'}],solution_text:'Using the expected frequencies from the row and column totals gives $\chi^2\approx14.73$ with $(4-1)(3-1)=6$ degrees of freedom. The upper-tail probability is $p\approx0.023$, so the p-value is $0.023$.',diagramRequired:false,uncertainties:[]},
  '21237': {question_text:'The graph below shows part of $f(x)=a\cos\bigl(b(x+c)\bigr)+d$. The local maximum and minimum points are shown at $\left(\dfrac\pi6,20\right)$ and $\left(\dfrac\pi3,4\right)$. Find the value of $a$.',structure:'find-cosine-amplitude-from-extrema',meaningfulCase:'amplitude-half-the-maximum-to-minimum-range',mastery:false,options:[{text:'$a=8$',correct:true},{text:'$a=20$',correct:false,why:'Uses the maximum value instead of half the vertical range.'},{text:'$a=16$',correct:false,why:'Uses the full difference between the maximum and minimum as the amplitude.'},{text:'$a=4$',correct:false,why:'Uses the minimum value rather than the amplitude of the oscillation.'}],solution_text:'The amplitude is half the difference between the local maximum and minimum values: $|a|=\dfrac{20-4}{2}=8$. The graph has a maximum at the labelled point, so $a=8$.',diagramRequired:true,uncertainties:[]},
  '21343': {question_text:'The graph below shows a particle\'s velocity, acceleration, and displacement. Which graph shows the displacement?\n\nA. displacement\nB. displacement\nC. displacement\nD. displacement',structure:'identify-displacement-from-related-kinematic-graphs',meaningfulCase:'displacement-is-an-antiderivative-of-velocity',mastery:false,options:[{text:'Graph A',correct:false,why:'Its straight decreasing form is consistent with constant acceleration, not displacement here.'},{text:'Graph B',correct:false,why:'This straight-line graph is the derivative relationship expected for acceleration.'},{text:'Graph C',correct:true},{text:'Graph D',correct:false,why:'This parabola has the relationship expected for velocity when displacement is cubic.'}],solution_text:'Displacement differentiates to velocity, and velocity differentiates to acceleration. The blue parabola has derivative equal to the purple straight line, while the red cubic-shaped graph differentiates to the blue parabola. Therefore the displacement is graph C.',diagramRequired:true,uncertainties:[]}
  ,'84744': {question_text:'Solve the equation $z^5=16-16i\sqrt3$, giving your answers in the form $re^{i\theta}$ where $\theta$ is in terms of $\pi$ and $0\leq\theta<2\pi$. Which of the following is a correct solution for $\theta$?',structure:'find-argument-of-complex-fifth-roots',meaningfulCase:'principal-argument-adjusted-to-required-range',mastery:false,options:[{text:'$\dfrac{29\pi}{15}$',correct:true},{text:'$-\dfrac\pi{15}$',correct:false,why:'This argument is equivalent modulo $2\pi$ but violates the required nonnegative range.'},{text:'Both are correct',correct:false,why:'Only the nonnegative representative satisfies the stated range for theta.'},{text:'Neither is correct',correct:false,why:'The first value is obtained from the valid fifth-root argument.'}],solution_text:'Write $16-16i\sqrt3=32e^{-i\pi/3}$. Taking fifth roots gives $r=2$ and $\theta=-\pi/15+2k\pi/5$. For $k=0$, the equivalent angle in $[0,2\pi)$ is $2\pi-\pi/15=29\pi/15$.',diagramRequired:false,uncertainties:[]}
  ,'11176': {question_text:'Find $\displaystyle\int\frac{2x+5}{x+1}\,dx$.',structure:'integrate-linear-over-linear-rational-function',meaningfulCase:'rewrite-rational-function-before-integration',mastery:false,options:[{text:'$2x+\dfrac13\ln(x+1)+c$',correct:false,why:'Uses an incorrect coefficient for the logarithmic remainder.'},{text:'$2x+3\ln(x+1)+c$',correct:false,why:'Omits the absolute value needed for the logarithm on the full domain.'},{text:'$2x+3\ln|x+1|+c$',correct:true},{text:'$2x+\dfrac13\ln|x+1|+c$',correct:false,why:'Uses an incorrect coefficient after dividing the remainder by the denominator.'}],solution_text:'Divide first: $\dfrac{2x+5}{x+1}=2+\dfrac3{x+1}$. Hence the integral is $2x+3\ln|x+1|+c$.',diagramRequired:false,uncertainties:[]}
  ,'11211': {question_text:'A parabola $y^2=3x$ is stretched with scale factor $\dfrac12$ in the $x$ direction, and scale factor $3$ in the $y$ direction. Which is the new equation of the parabola?',structure:'transform-conic-equation-by-independent-axis-scales',meaningfulCase:'coordinate-substitution-for-horizontal-and-vertical-stretches',mastery:false,options:[{text:'$y^2=54x$',correct:true},{text:'$y^2=\dfrac12x$',correct:false,why:'Applies only the horizontal scale and ignores the vertical scale.'},{text:'$y^2=18x$',correct:false,why:'Uses the vertical scale incorrectly without the horizontal substitution.'},{text:'$y^2=\dfrac16x$',correct:false,why:'Combines the scale factors in the wrong direction.'}],solution_text:'Let the new coordinates be $(X,Y)$, so the old coordinates are $x=2X$ and $y=Y/3$. Substituting gives $(Y/3)^2=3(2X)$, hence $Y^2=54X$.',diagramRequired:false,uncertainties:[]}
  ,'11214': {question_text:'The hyperbola $\dfrac{x^2}{2}-\dfrac{y^2}{3}=1$ is translated by the vector $\begin{pmatrix}2\\-1\end{pmatrix}$. Which is the new equation of the hyperbola?',structure:'translate-conic-equation-by-vector',meaningfulCase:'replace-old-coordinates-after-horizontal-and-vertical-translation',mastery:false,options:[{text:'$\dfrac{(x+2)^2}{2}-\dfrac{(y-1)^2}{3}=1$',correct:false,why:'Uses the opposite translation signs in both coordinate substitutions.'},{text:'$\dfrac{(x-2)^2}{2}-\dfrac{(y+1)^2}{3}=1$',correct:true},{text:'$\dfrac{(x-2)^2}{2}-\dfrac{y^2}{3}=0$',correct:false,why:'Drops the vertical translation and changes the right-hand constant.'},{text:'$\dfrac{x^2-2}{2}-\dfrac{y^2+1}{3}=1$',correct:false,why:'Subtracts constants outside the squared coordinate brackets incorrectly.'}],solution_text:'A translation by $(2,-1)$ sends old coordinates to $(x-2,y+1)$ when expressed in the new equation. Therefore $\dfrac{(x-2)^2}{2}-\dfrac{(y+1)^2}{3}=1$.',diagramRequired:false,uncertainties:[]}
  ,'11238': {question_text:'$Z\sim N(0,1)$ and the unshaded central area represents $90\%$ of the total area. What number lies underneath the star?',structure:'find-standard-normal-quantile-from-central-area',meaningfulCase:'symmetric-central-interval-with-five-percent-each-tail',mastery:false,options:[{text:'$-1.65$',correct:true},{text:'$-1.96$',correct:false,why:'Uses the 95% central interval rather than the 90% central interval.'},{text:'$-1.28$',correct:false,why:'Uses a one-tailed 90th-percentile value rather than the 5% lower tail.'},{text:'$1.28$',correct:false,why:'Has the wrong sign and corresponds to a different tail probability.'}],solution_text:'If the central area is $0.90$, each tail has area $0.05$. The lower 5% standard-normal quantile is about $-1.645$, which rounds to $-1.65$.',diagramRequired:true,uncertainties:[]}
  ,'121297': {question_text:'Which of these scenarios can be modelled with the binomial distribution?\n\nA. Rolling a dice until you get a six\nB. Picking counters out of a bag without replacing them each time\nC. Randomly guessing the answers in this multiple-choice quiz\nD. Rolling a dice then flipping a coin',structure:'recognise-binomial-scenario-from-trial-conditions',meaningfulCase:'fixed-number-of-independent-identical-trials',mastery:false,options:[{text:'A',correct:false,why:'The number of trials is random because the process stops at the first six.'},{text:'B',correct:false,why:'Without replacement makes the probability of success change each draw.'},{text:'C',correct:true},{text:'D',correct:false,why:'This describes two different single outcomes rather than a fixed count of repeated trials.'}],solution_text:'A binomial model requires a fixed number of independent trials, two outcomes per trial, and a constant success probability. Randomly guessing a fixed number of quiz answers satisfies these conditions, so the answer is C.',diagramRequired:false,uncertainties:[]}
  ,'121476': {question_text:'What is the mass of an object which has a weight of $10\,\mathrm N$?',structure:'calculate-mass-from-weight',meaningfulCase:'use-weight-equals-mass-times-gravitational-field-strength',mastery:false,options:[{text:'$98\,\mathrm N$',correct:false,why:'Keeps force units and does not calculate the mass from the weight.'},{text:'$1.0\,\mathrm N$',correct:false,why:'Uses the approximate numerical mass but gives it the wrong unit.'},{text:'$98\,\mathrm{kg}$',correct:false,why:'Multiplies by gravitational field strength instead of dividing by it.'},{text:'$1.0\,\mathrm{kg}$',correct:true}],solution_text:'Using $W=mg$ with $g=9.8\,\mathrm{m\,s^{-2}}$, $m=W/g=10/9.8\approx1.0\,\mathrm{kg}$.',diagramRequired:false,uncertainties:[]}
  ,'123994': {question_text:'A vaccine has an advertised success rate of $95\%$. A group of 100 people is vaccinated and 98 are found to be immune. Test, at the $5\%$ significance level, whether there is sufficient evidence that the vaccine is actually more effective than advertised. What are the two hypotheses?',structure:'state-one-tailed-binomial-test-hypotheses',meaningfulCase:'upper-tail-alternative-for-success-rate',mastery:false,options:[{text:'$H_0:p=0.95,\quad H_1:p\ne0.95$',correct:false,why:'Uses a two-tailed alternative although the question asks whether effectiveness is greater.'},{text:'$H_0:p=0.95,\quad H_1:p>0.95$',correct:true},{text:'$H_0=0.95,\quad H_1>0.95$',correct:false,why:'Does not state the hypotheses as statements about the population proportion.'},{text:'$H_0:p=0.95,\quad H_1:p=0.98$',correct:false,why:'Uses the observed sample proportion as the alternative hypothesis value.'}],solution_text:'The advertised rate is the null value, so $H_0:p=0.95$. Because the test asks whether the true rate is higher, the alternative is $H_1:p>0.95$.',diagramRequired:false,uncertainties:[]}
  ,'123995': {question_text:'A vaccine has an advertised success rate of $95\%$. A group of 100 people is vaccinated and 98 are found to be immune. Let $X$ be the number of people in the sample who receive immunity from the vaccine. When is $X\sim B(100,0.95)$?',structure:'identify-null-model-condition-in-hypothesis-test',meaningfulCase:'binomial-model-uses-null-probability-when-null-is-true',mastery:false,options:[{text:'Always',correct:false,why:'The binomial parameter is not fixed at 0.95 if the advertised rate is false.'},{text:'If $H_0$ is true',correct:true},{text:'If $H_0$ is false',correct:false,why:'Under a false null, the true success probability is not 0.95.'},{text:'Never',correct:false,why:'The stated binomial model is valid when the null success probability holds.'}],solution_text:'The model $B(100,0.95)$ assumes each person has success probability $0.95$. That is precisely the null hypothesis, so the model applies if $H_0$ is true.',diagramRequired:false,uncertainties:[]}
  ,'13322': {question_text:'Convert $6\left(\cos\dfrac{2\pi}{3}+i\sin\dfrac{2\pi}{3}\right)$ into the form $x+iy$.',structure:'convert-complex-number-from-polar-to-cartesian-form',meaningfulCase:'evaluate-special-angle-sine-and-cosine',mastery:false,options:[{text:'$z=\dfrac{\sqrt3}{2}i-\dfrac12$',correct:false,why:'Omits the factor 6 when converting from polar form.'},{text:'$3+3\sqrt3i$',correct:false,why:'Uses the wrong sign for the cosine at angle $2\pi/3$.'},{text:'$z=\dfrac12+\dfrac{\sqrt3}{2}i$',correct:false,why:'Gives the unit-circle coordinates and omits the modulus 6.'},{text:'$3\sqrt3i-3$',correct:true}],solution_text:'Since $\cos(2\pi/3)=-1/2$ and $\sin(2\pi/3)=\sqrt3/2$, the number is $6(-1/2+i\sqrt3/2)=-3+3\sqrt3i$.',diagramRequired:false,uncertainties:[]}
  ,'2308': {question_text:'What is the equation of the tangent to the stationary point of this parabola? The stationary point is $(1,6)$.',structure:'find-horizontal-tangent-at-stationary-point',meaningfulCase:'stationary-point-tangent-is-horizontal',mastery:false,options:[{text:'$x=1$',correct:false,why:'This is the vertical line through the stationary point, not its tangent.'},{text:'$x=6$',correct:false,why:'Uses the y-coordinate as a vertical-line equation.'},{text:'$y=6$',correct:true},{text:'$y=x+5$',correct:false,why:'Has gradient 1 rather than the zero gradient at a stationary point.'}],solution_text:'At a stationary point the gradient is zero, so the tangent is horizontal. Passing through $(1,6)$ gives $y=6$.',diagramRequired:true,uncertainties:[]}
  ,'4113': {question_text:'The equation of the tangent to a circle at a point is $y-4=4(x-3)$. What is the gradient of the normal at this point?',structure:'find-normal-gradient-from-tangent-gradient',meaningfulCase:'negative-reciprocal-of-nonzero-tangent-gradient',mastery:false,options:[{text:'$4$',correct:false,why:'Repeats the tangent gradient instead of using the perpendicular normal.'},{text:'$-4$',correct:false,why:'Changes the sign but does not take the reciprocal.'},{text:'$\dfrac14$',correct:false,why:'Takes the reciprocal but keeps the tangent gradient sign.'},{text:'$-\dfrac14$',correct:true}],solution_text:'The tangent has gradient $4$. A perpendicular line has gradient equal to the negative reciprocal, so the normal gradient is $-1/4$.',diagramRequired:false,uncertainties:[]}
  ,'66509': {question_text:'Let $\mathbf a=a_1\mathbf i+a_2\mathbf j+a_3\mathbf k$ and $\mathbf b=b_1\mathbf i+b_2\mathbf j+b_3\mathbf k$. Which option gives the vector product $\mathbf a\times\mathbf b$?',structure:'expand-three-dimensional-vector-cross-product',meaningfulCase:'determinant-expansion-with-middle-term-negative',mastery:false,options:[{text:'$\left|\begin{matrix}a_2&b_2\\a_3&b_3\end{matrix}\right|\mathbf i-\left|\begin{matrix}a_1&b_1\\a_3&b_3\end{matrix}\right|\mathbf j+\left|\begin{matrix}a_1&b_1\\a_2&b_2\end{matrix}\right|\mathbf k$',correct:true},{text:'$\left|\begin{matrix}a_2&b_2\\a_3&b_3\end{matrix}\right|\mathbf i-\left|\begin{matrix}a_1&b_1\\a_3&b_3\end{matrix}\right|\mathbf j+\left|\begin{matrix}a_1&b_1\\a_2&b_2\end{matrix}\right|\mathbf k$',correct:false,why:'This option duplicates the standard expansion and does not provide a distinct alternative.'},{text:'$\left|\begin{matrix}a_2&b_2\\a_3&b_3\end{matrix}\right|\mathbf i+\left|\begin{matrix}a_1&b_1\\a_3&b_3\end{matrix}\right|\mathbf j-\left|\begin{matrix}a_1&b_1\\a_2&b_2\end{matrix}\right|\mathbf k$',correct:false,why:'Uses the wrong signs for the middle and final components.'},{text:'$\left|\begin{matrix}b_2&a_2\\b_3&a_3\end{matrix}\right|\mathbf i-\left|\begin{matrix}b_1&a_1\\b_3&a_3\end{matrix}\right|\mathbf j+\left|\begin{matrix}b_1&a_1\\b_2&a_2\end{matrix}\right|\mathbf k$',correct:false,why:'Reverses the determinant columns and therefore gives the opposite cross product.'}],solution_text:'Expand the determinant with rows $(\mathbf i,\mathbf j,\mathbf k)$, $(a_1,a_2,a_3)$ and $(b_1,b_2,b_3)$. This gives the $\mathbf i$ minor minus the $\mathbf j$ minor plus the $\mathbf k$ minor shown in option A.',diagramRequired:false,uncertainties:['Options A and B appear visually identical in the supplied image; the source does not make a unique distinction between them.']}
  ,'91751': {question_text:'Which of the following is not true about a complex number $z$ and its conjugate $z^*$?',structure:'identify-false-property-of-complex-conjugates',meaningfulCase:'conjugation-reflects-points-in-real-axis',mastery:false,options:[{text:'Their product is always real',correct:false,why:'Indeed $zz^*=|z|^2$, which is real.'},{text:'Their sum is always real',correct:false,why:'Indeed $z+z^*=2\operatorname{Re}(z)$, which is real.'},{text:'They are symmetrical about the real axis.',correct:false,why:'Complex conjugation reflects a point across the real axis.'},{text:'They are symmetrical about the imaginary axis',correct:true}],solution_text:'The conjugate changes the sign of the imaginary part and therefore gives reflection in the real axis. Reflection in the imaginary axis would map $z$ to $-z^*$, not to $z^*$.',diagramRequired:false,uncertainties:[]}
  ,'9705': {question_text:'If the following function is rotated $2\pi$ radians about the $x$-axis, the volume generated would look like which of the following?',structure:'recognise-solid-of-revolution-about-x-axis',meaningfulCase:'rotating-a-curved-increasing-function-around-horizontal-axis',mastery:false,options:[{text:'A',correct:true},{text:'B',correct:false,why:'A cylinder has constant radius, unlike the changing radius of the curve.'},{text:'C',correct:false,why:'A cone or frustum comes from a linear radius function, not this curve.'},{text:'D',correct:false,why:'The bulbous profile does not match the shown increasing curved function.'}],solution_text:'Rotating the graph about the $x$-axis produces circular cross-sections whose radius is the function value. Since the radius changes nonlinearly along $x$, the generated solid has the curved profile shown in A.',diagramRequired:true,uncertainties:['The source graph has no explicit equation or scale labels, so the identification relies on its visible curved profile.']}
  ,'8551': {question_text:'What does $6g-2h+h$ simplify to?',structure:'collect-like-algebraic-terms',meaningfulCase:'combine-coefficients-of-the-same-variable',mastery:false,options:[{text:'$4gh^2$',correct:false,why:'Multiplies unlike terms and introduces powers that are not present.'},{text:'$6g+3h$',correct:false,why:'Adds the coefficients of $-2h$ and $h$ instead of subtracting them.'},{text:'$6g-3h$',correct:false,why:'Treats the coefficient of $h$ as if both terms were negative.'},{text:'None of the above',correct:true}],solution_text:'Only the $h$ terms combine: $-2h+h=-h$. Thus the simplified expression is $6g-h$, which is not listed.',diagramRequired:false,uncertainties:[]}
  ,'96253': {question_text:'The minimum point of $f(x)$ is $(-6,3)$. What is the minimum point of $f(3x)$?',structure:'transform-turning-point-under-horizontal-compression',meaningfulCase:'horizontal-coordinate-divided-by-inside-factor',mastery:false,options:[{text:'$(-18,3)$',correct:false,why:'Multiplies the x-coordinate instead of applying horizontal compression.'},{text:'$(-6,1)$',correct:false,why:'Changes the y-coordinate even though the transformation is horizontal.'},{text:'$(-2,3)$',correct:true},{text:'$(-6,9)$',correct:false,why:'Changes the y-coordinate and leaves the horizontal coordinate unchanged.'}],solution_text:'For $g(x)=f(3x)$, the input must equal $-6$ at the minimum, so $3x=-6$ and $x=-2$. The output remains $3$, giving $(-2,3)$.',diagramRequired:false,uncertainties:[]}
  ,'180061': {question_text:'When drawing an accurate copy of this shape, where should you place your protractor to measure the $80^\circ$ angle? The $80^\circ$ angle is at the left-hand vertex of the side of length $7\,\mathrm{cm}$.',structure:'position-protractor-at-angle-vertex',meaningfulCase:'centre-at-vertex-baseline-along-one-arm',mastery:false,options:[{text:'A',correct:true},{text:'B',correct:false,why:'Places the protractor centre at the wrong end of the 7 cm side.'}],solution_text:'Place the protractor centre exactly on the vertex of the $80^\circ$ angle and align its baseline with the 7 cm side. Diagram A shows this placement.',diagramRequired:true,uncertainties:[]}
  ,'28359': {question_text:'How many planes of symmetry does this cone have?',structure:'count-planes-of-symmetry-of-right-circular-cone',meaningfulCase:'every-vertical-plane-through-axis-is-a-symmetry-plane',mastery:false,options:[{text:'1',correct:false,why:'Counts only the horizontal base-related plane and misses the vertical planes.'},{text:'2',correct:false,why:'There are more than two planes through the cone axis.'},{text:'3D shapes cannot have symmetry',correct:false,why:'Three-dimensional solids can have planes of symmetry.'},{text:'Infinite',correct:true}],solution_text:'A right circular cone is unchanged by reflection in any plane containing its central axis. There are infinitely many such planes, so the answer is infinite.',diagramRequired:true,uncertainties:[]}
  ,'11167': {question_text:'Find a correct form of $f\prime(x)$ if $f(x)=\ln\left[\dfrac{e^x}{x+1}\right]$.',structure:'differentiate-logarithm-of-quotient',meaningfulCase:'logarithm-laws-before-differentiating',mastery:false,options:[{text:'$x(x+1)$',correct:false,why:'Multiplies the factors instead of differentiating the logarithmic expression.'},{text:'$\dfrac{x+1}{e^x}$',correct:false,why:'Uses the reciprocal of an unrelated quotient rather than the derivative.'},{text:'$\dfrac{x}{x+1}$',correct:true},{text:'$\dfrac1{(x+1)^2}$',correct:false,why:'Differentiates a reciprocal expression and misses the exponential logarithm term.'}],solution_text:'Use logarithm laws: $f(x)=x-\ln|x+1|$. Therefore $f\prime(x)=1-\dfrac1{x+1}=\dfrac{x}{x+1}$.',diagramRequired:false,uncertainties:[]}
  ,'11260': {question_text:'What does $\displaystyle\lim_{x\to\infty}\frac{x^3-5x^2+x-4}{4x^3-3x^2+2x-6}$ equal?',structure:'evaluate-rational-function-limit-at-infinity',meaningfulCase:'ratio-of-leading-coefficients-for-equal-degree-polynomials',mastery:false,options:[{text:'$\dfrac14$',correct:true},{text:'$1$',correct:false,why:'Treats the numerator and denominator as having equal leading coefficients.'},{text:'$0$',correct:false,why:'Uses the rule for a lower-degree numerator rather than equal degrees.'},{text:'$4$',correct:false,why:'Reverses the ratio of the leading coefficients.'}],solution_text:'Divide numerator and denominator by $x^3$. As $x\to\infty$, the lower-degree terms vanish, leaving $1/4$.',diagramRequired:false,uncertainties:[]}
  ,'125777': {question_text:'You are finding the minimum spanning tree for this network using Prim. This is correct so far. Finish the algorithm and give the length of the minimum connector.',structure:'complete-prims-algorithm-and-total-edge-weight',meaningfulCase:'choose-smallest-edge-connecting-new-vertex',mastery:false,options:[{text:'170',correct:false,why:'Omits one of the required connecting edges in the spanning tree.'},{text:'172',correct:false,why:'Adds an incorrect edge weight while completing the network.'},{text:'174',correct:true},{text:'176',correct:false,why:'Selects a larger available edge instead of the smallest valid continuation.'}],solution_text:'Starting with the shown edges $AC=30$, $CD=22$, $DE=18$ and $BD=24$, Prim next selects $EG=26$, then $FG=21$ and $GH=33$. The total is $30+22+18+24+26+21+33=174$.',diagramRequired:true,uncertainties:[]}
  ,'20823': {question_text:'The heights (cm) of 8 students are $172,168,167,168,171,178,175,162$. Calculate the standard deviation of the heights.',structure:'calculate-standard-deviation-from-raw-data',meaningfulCase:'population-standard-deviation-from-eight-values',mastery:false,options:[{text:'$4.99$',correct:false,why:'Rounds the calculated standard deviation to an incorrect nearby value.'},{text:'$5$',correct:false,why:'Uses an overly coarse rounding rather than the listed answer precision.'},{text:'$5.01$',correct:false,why:'Does not match the square root of the mean squared deviation.'},{text:'$4.68$',correct:true}],solution_text:'The mean is $170$. The sum of squared deviations is $175$, so the population variance is $175/8=21.875$. Thus $\sigma=\sqrt{21.875}=4.677\ldots\approx4.68$.',diagramRequired:false,uncertainties:[]}
  ,'20847': {question_text:'The temperature $T^\circ$ is measured for 12 days against the number of ice creams sold $C$. The data are $T=(15,16,18,20,24,27,23,19,18,20,17,16)$ and $C=(22,25,32,33,28,43,38,30,21,37,23,18)$. Use the data to find the number of ice creams sold when the temperature is $22^\circ$.',structure:'estimate-regression-value-from-bivariate-data',meaningfulCase:'linear-regression-interpolation-at-temperature',mastery:false,options:[{text:'28',correct:false,why:'Uses a nearby observed sales value without applying the regression estimate.'},{text:'33',correct:false,why:'Repeats a recorded value at 20 degrees rather than estimating at 22.'},{text:'23',correct:false,why:'Uses a low observed sales count that is not the fitted estimate.'},{text:'36',correct:true}],solution_text:'Using the least-squares regression line of sales on temperature for the twelve pairs gives a fitted sales value of approximately $36$ when $T=22$.',diagramRequired:false,uncertainties:['The screenshot does not state whether the intended estimate is from a regression line or a particular interpolation rule; the answer is inferred as the standard linear-regression estimate.']}
  ,'89574': {question_text:'Which calculation is equal to $-20$?',structure:'evaluate-order-of-operations-with-negative-numbers',meaningfulCase:'division-and-subtraction-with-negative-operands',mastery:false,options:[{text:'$(-3)^2-11$',correct:false,why:'This evaluates to $-2$, not the requested negative twenty.'},{text:'$3\times(-4)-(-4)\times2$',correct:false,why:'The two products cancel to give $-4$, not $-20$.'},{text:'$-28-(-4)\times(-2)$',correct:false,why:'Multiplication gives positive eight, leaving $-36$.'},{text:'$(-33)\div(-3)-31$',correct:true}],solution_text:'Evaluate the last expression using division first: $(-33)\div(-3)-31=11-31=-20$.',diagramRequired:false,uncertainties:[]}
  ,'141338': {question_text:'Which division equation does this bar model represent? The whole bar is $1$ and the highlighted part is $\dfrac13$ of the whole.',structure:'interpret-fraction-bar-model-as-division-equation',meaningfulCase:'fraction-of-whole-divided-by-one-whole',mastery:false,options:[{text:'$\dfrac12\div3=\dfrac16$',correct:false,why:'Uses the wrong highlighted fraction and therefore models a different bar.'},{text:'$\dfrac13\div1=\dfrac13$',correct:true},{text:'$1\div\dfrac13=\dfrac31$',correct:false,why:'Reverses the dividend and divisor represented by the highlighted part.'},{text:'$\dfrac12\div3=\dfrac13$',correct:false,why:'The displayed equality is numerically false and uses the wrong numerator.'}],solution_text:'The highlighted section is one third of a whole of size $1$. Therefore the model represents $\dfrac13\div1=\dfrac13$.',diagramRequired:true,uncertainties:[]}
  ,'17378': {question_text:'There are 180 students in Year 12. 22 students are left-handed, 57 students wear glasses, and 13 students are left-handed and wear glasses. Work out how many students are neither left-handed nor wear glasses.',structure:'calculate-complement-of-union-by-inclusion-exclusion',meaningfulCase:'subtract-overlapping-union-from-total',mastery:false,options:[{text:'92',correct:false,why:'Subtracts the two group totals without handling their overlap correctly.'},{text:'88',correct:false,why:'Uses an incorrect union total after adjusting for the intersection.'},{text:'127',correct:false,why:'Subtracts the sum of the groups without adding back the overlap.'},{text:'114',correct:true}],solution_text:'The number in at least one group is $22+57-13=66$. Hence the number in neither group is $180-66=114$.',diagramRequired:false,uncertainties:[]}
  ,'11265': {question_text:'If $0<a<1$, what does $\displaystyle\lim_{x\to\infty}\log_a(x)$ equal?',structure:'evaluate-logarithmic-limit-for-base-between-zero-and-one',meaningfulCase:'decreasing-logarithm-tends-to-negative-infinity',mastery:false,options:[{text:'$0$',correct:false,why:'Confuses the logarithm limit with a power limit at zero.'},{text:'$+\infty$',correct:false,why:'Uses the increasing-logarithm behaviour for a base greater than one.'},{text:'$-\infty$',correct:true},{text:'$1$',correct:false,why:'Treats the logarithm as a constant instead of a decreasing unbounded function.'}],solution_text:'For $0<a<1$, the logarithm is decreasing. As $x$ increases without bound, $\log_a(x)$ decreases without bound, so the limit is $-\infty$.',diagramRequired:false,uncertainties:[]}
  ,'125259': {question_text:'What is the value of $F_r$ for a $5\,\mathrm{kg}$ block on a horizontal surface with coefficient of friction $\mu=0.5$ and a $30\,\mathrm N$ force to the right?',structure:'calculate-limiting-friction-from-coefficient-and-normal-reaction',meaningfulCase:'friction-opposes-motion-and-equals-mu-r-at-limit',mastery:false,options:[{text:'$24.5\,\mathrm N$',correct:true},{text:'$0\,\mathrm N$',correct:false,why:'Assumes no friction despite the applied force exceeding the limiting value.'},{text:'$49\,\mathrm N$',correct:false,why:'Uses the weight or normal reaction without multiplying by the coefficient.'},{text:'$30\,\mathrm N$',correct:false,why:'Sets friction equal to the applied force without using $\mu R$.'}],solution_text:'The normal reaction is $R=mg=5(9.8)=49\,\mathrm N$. Thus the limiting friction is $F_r=\mu R=0.5(49)=24.5\,\mathrm N$.',diagramRequired:true,uncertainties:[]}
  ,'145671': {question_text:'What is $\dfrac18$ as a decimal?',structure:'convert-unit-fraction-to-decimal',meaningfulCase:'terminate-decimal-from-eighths',mastery:false,options:[{text:'$0.12$',correct:false,why:'Rounds too early and omits the final digits of the exact decimal.'},{text:'$0.125$',correct:true},{text:'$0.18$',correct:false,why:'Uses the denominator digits as if they formed the decimal value.'},{text:'$1.8$',correct:false,why:'Places the decimal point incorrectly and gives a value greater than one.'}],solution_text:'Since $1\div8=0.125$, the decimal equivalent is $0.125$.',diagramRequired:false,uncertainties:[]}
  ,'128001': {question_text:'Which diagram correctly depicts the curve and solutions of $(x-2)(x+1)\geq0$?',structure:'solve-factorised-quadratic-inequality-graphically',meaningfulCase:'upward-parabola-solution-outside-the-roots',mastery:false,options:[{text:'A',correct:false,why:'Shows a downward-opening curve and shades the region between the roots.'},{text:'B',correct:true},{text:'C',correct:false,why:'Does not show the required combination of curve and shaded solution regions.'},{text:'D',correct:false,why:'Shows a downward-opening parabola rather than the positive-leading-term curve.'}],solution_text:'The roots are $x=-1$ and $x=2$. The leading coefficient is positive, so the parabola opens upward and is nonnegative outside the roots: $x\leq-1$ or $x\geq2$. The matching diagram is B.',diagramRequired:true,uncertainties:['The small shaded graph labels are low resolution, so the option identification is based on the visible parabola and outside shading.']}
  ,'128443': {question_text:'Calculate $4\dfrac15-2\dfrac14$, leaving your answer as a mixed number.',structure:'subtract-mixed-numbers-with-unlike-fractions',meaningfulCase:'borrow-and-use-common-denominator',mastery:false,options:[{text:'$2\dfrac{-1}{20}$',correct:false,why:'Fails to borrow correctly when subtracting the fractional parts.'},{text:'$2\dfrac1{20}$',correct:false,why:'Uses the wrong whole-number result after combining the fractions.'},{text:'$1\dfrac1{20}$',correct:false,why:'Subtracts the fractional parts but loses a whole during borrowing.'},{text:'$1\dfrac{19}{20}$',correct:true}],solution_text:'Convert to twentieths: $4\dfrac15=4\dfrac4{20}$ and $2\dfrac14=2\dfrac5{20}$. Borrowing gives $3\dfrac{24}{20}-2\dfrac5{20}=1\dfrac{19}{20}$.',diagramRequired:false,uncertainties:[]}
  ,'151095': {question_text:'For a particular curve, $\dfrac{dy}{dx}=\dfrac{f(y)}{g(x)}$, where $f$ and $g$ are unknown functions. Which of the following finds where the curve is parallel to the $y$-axis?',structure:'identify-vertical-tangent-condition-from-separable-derivative',meaningfulCase:'vertical-tangent-when-denominator-is-zero',mastery:false,options:[{text:'$g(x)=1$',correct:false,why:'This gives an ordinary finite derivative rather than a vertical tangent.'},{text:'$f(y)=1$',correct:false,why:'A nonzero numerator does not make the derivative vertical.'},{text:'$g(x)=0$',correct:true},{text:'$f(y)=0$',correct:false,why:'This makes the derivative zero, corresponding to a horizontal tangent.'}],solution_text:'A curve parallel to the $y$-axis has an undefined or infinite gradient. In $dy/dx=f(y)/g(x)$ this occurs when the denominator $g(x)$ is zero while the numerator is nonzero, so the condition is $g(x)=0$.',diagramRequired:false,uncertainties:[]}
  ,'17266': {question_text:'In the region $0<x\leq2\pi$, the equation $\displaystyle\int_0^x\sin(\sin t)\,dt=0$ has how many solutions?',structure:'count-zeros-of-integral-of-periodic-function',meaningfulCase:'one-return-to-zero-after-positive-and-negative-halves',mastery:false,options:[{text:'No solution',correct:false,why:'The integral returns to zero at the end of the stated interval.'},{text:'One solution',correct:true},{text:'Two solutions',correct:false,why:'Counts the excluded endpoint $x=0$ as an additional solution.'},{text:'Three solutions',correct:false,why:'The integral changes monotonically on each half and has only one allowed zero.'}],solution_text:'For $0<t<\pi$, $\sin(\sin t)>0$, so the integral is positive. For $\pi<t<2\pi$ it is negative and, by symmetry, the accumulated integral returns to zero at $x=2\pi$. Since $x=0$ is excluded, there is one solution.',diagramRequired:false,uncertainties:[]}
  ,'178736': {question_text:'I think of a number $q$. I divide my number by 12. I get 7. Which equation represents this?',structure:'translate-verbal-division-statement-into-equation',meaningfulCase:'unknown-number-as-dividend',mastery:false,options:[{text:'$\dfrac{12}{q}=7$',correct:false,why:'Uses the unknown as divisor instead of dividing the unknown by 12.'},{text:'$q-12=7$',correct:false,why:'Represents subtraction rather than division.'},{text:'$\dfrac q{12}=7$',correct:true},{text:'$\dfrac{12}{7}=q$',correct:false,why:'Rearranges the relationship incorrectly and does not state the given operation.'}],solution_text:'“My number divided by 12 is 7” translates directly to $q/12=7$.',diagramRequired:false,uncertainties:[]}
  ,'122825': {question_text:'$4x-3\equiv A(x+3)^2+B(x-2)(x+3)+C(x-2)$. You could find the values of $A$, $B$, and $C$ by substituting values of $x$. Which of these would you not pick though?',structure:'choose-substitution-values-for-partial-fractions-identity',meaningfulCase:'use-roots-to-eliminate-terms-when-solving-coefficients',mastery:false,options:[{text:'$x=2$',correct:false,why:'This value eliminates two terms and isolates coefficient $A$.'},{text:'$x=0$',correct:true,why:'This value does not eliminate any term, so it gives a less useful equation.'},{text:'$x=-3$',correct:false,why:'This value eliminates two terms and isolates coefficient $C$.'},{text:'$x=3$',correct:false,why:'This is a valid non-root substitution for obtaining a third equation.'}],solution_text:'Choosing $x=2$ isolates $A$, and choosing $x=-3$ isolates $C$. A third value should be a convenient non-root; $x=3$ works, whereas $x=0$ makes all three terms remain and is the least useful choice. Therefore the intended answer is $x=0$.',diagramRequired:false,uncertainties:['The wording says any values may be substituted, so $x=0$ is mathematically valid; it is selected only as the least useful of the displayed choices.']}
  ,'124380': {question_text:'A beam $AD$ rests on pivots at $A$ and $B$. A person of mass $m$ stands at $C$, with $AB:AD=3:4$ and $AC:AB=1:2$. The beam has mass $M$ acting at $E$. At tipping clockwise about $B$, $DE:DA=k:1$. Find an inequality for $M$ in terms of $m$.',structure:'analyse-tipping-beam-by-taking-moments',meaningfulCase:'clockwise-tipping-threshold-depends-on-beam-centre-position',mastery:false,options:[{text:'$M<2m$',correct:false,why:'Assumes a fixed beam-centre position that is not supplied by the question.'},{text:'$M>2m$',correct:false,why:'Gives a numerical threshold without enough information about $E$.'},{text:'Not enough information in the question',correct:true},{text:'$m>0$',correct:false,why:'States only the physical positivity of the person mass, not the tipping inequality.'}],solution_text:'Taking moments about $B$ requires the distance $BE$, which depends on the unspecified value of $k$ and the position of the beam centre. Without that information, no unique inequality for $M$ in terms of $m$ can be determined.',diagramRequired:true,uncertainties:[]}
  ,'125663': {question_text:'For which of these histograms would the normal distribution be a good model?',structure:'recognise-normal-distribution-from-histogram-shape',meaningfulCase:'approximately-symmetric-unimodal-bell-shaped-data',mastery:false,options:[{text:'A',correct:false,why:'The histogram is irregular and not approximately symmetric about its centre.'},{text:'B',correct:false,why:'The strong right skew is inconsistent with a normal model.'},{text:'C',correct:true},{text:'D',correct:false,why:'The nearly uniform shape is not the bell shape of a normal distribution.'}],solution_text:'A normal distribution is unimodal and approximately symmetric with frequencies tapering away from the centre. Histogram C has this bell-shaped form.',diagramRequired:true,uncertainties:[]}
  ,'125782': {question_text:'You are finding the MST for this network using Prim, starting at $X$. The edges selected so far are $XU(16)$ and $UW(14)$. Which value do you select next?',structure:'select-next-edge-in-prims-minimum-spanning-tree',meaningfulCase:'smallest-edge-from-current-tree-to-unvisited-vertex',mastery:false,options:[{text:'$UY(18)$',correct:false,why:'Although it joins an unvisited vertex, it is larger than the available edge of weight 17.'},{text:'$XY(20)$',correct:false,why:'This edge is already incident to the starting tree but is not the smallest candidate.'},{text:'$VW(21)$',correct:false,why:'It is not the smallest edge crossing from the current tree.'},{text:'$WY(17)$',correct:true}],solution_text:'The current tree contains $X,U,W$. The available edges to an unvisited vertex include $UY=18$ and $WY=17$; Prim selects the smaller valid edge, $WY(17)$.',diagramRequired:false,uncertainties:[]}
  ,'132411': {question_text:'A normal distribution has mean $\mu=200$. If $70\%$ of the area under the curve lies to the left of 210, the area to the right of 210 is:',structure:'find-complementary-normal-tail-area',meaningfulCase:'right-tail-is-complement-of-left-cumulative-area',mastery:false,options:[{text:'$0.30$',correct:true},{text:'$0.50$',correct:false,why:'Uses the area on one side of the mean rather than the stated cumulative area.'},{text:'$0.03$',correct:false,why:'Confuses a percentage conversion with the complement of 70 percent.'},{text:'$0.20$',correct:false,why:'Subtracts the given percentage from an unrelated reference value.'}],solution_text:'The total area is 1. Therefore the area to the right is $1-0.70=0.30$.',diagramRequired:false,uncertainties:[]}
  ,'95472': {question_text:'What is the order of rotational symmetry of this four-point shape?',structure:'determine-order-of-rotational-symmetry',meaningfulCase:'half-turn-maps-opposite-points-onto-each-other',mastery:false,options:[{text:'0',correct:false,why:'Every closed shape has at least the identity rotation symmetry.'},{text:'1',correct:false,why:'The shape matches itself again after a half-turn as well as the full turn.'},{text:'2',correct:true},{text:'4',correct:false,why:'A quarter-turn swaps unequal arms and does not reproduce the shape.'}],solution_text:'A rotation of $180^\circ$ maps the long vertical points and the horizontal points onto their opposites. No $90^\circ$ rotation works, so the order is $2$.',diagramRequired:true,uncertainties:[]}
  ,'96255': {question_text:'The minimum point of $f(x)$ is $(2,-1)$. What is the maximum point of $-f(x)$?',structure:'reflect-turning-point-in-x-axis',meaningfulCase:'negating-function-reverses-vertical-extremum',mastery:false,options:[{text:'$(-2,-1)$',correct:false,why:'Changes the x-coordinate even though the transformation is vertical.'},{text:'$(2,1)$',correct:true},{text:'$(-2,1)$',correct:false,why:'Changes the x-coordinate as well as reversing the y-coordinate.'},{text:'$(2,-1)$',correct:false,why:'Leaves the original minimum unchanged instead of reflecting its y-value.'}],solution_text:'Negating the function reflects the graph in the $x$-axis. The point $(2,-1)$ therefore maps to $(2,1)$, which is a maximum.',diagramRequired:false,uncertainties:[]}
  ,'151089': {question_text:'Which of the following is not an implicitly defined curve?\n\nA. $x^3-x=y$\nB. $x^2y^2=1$\nC. $y^2=1-x^2$\nD. $y^3-y=x$',structure:'distinguish-explicit-and-implicit-curve-equations',meaningfulCase:'equation-with-y-already-isolated-is-explicit',mastery:false,options:[{text:'A',correct:true},{text:'B',correct:false,why:'Both variables remain in a joint equation, so this is implicit.'},{text:'C',correct:false,why:'The equation relates x and y without isolating one as a single-valued function.'},{text:'D',correct:false,why:'The cubic relation leaves y implicit even though x is on the right.'}],solution_text:'In A, the equation is already written as $y=x^3-x$, an explicit function of $x$. The other relations leave the variables jointly defined, so A is the one that is not implicit.',diagramRequired:false,uncertainties:[]}
  ,'22463': {question_text:'Shape $P$ is transformed to shape $Q$ by a rotation $90^\circ$ clockwise, centre $O$, followed by a reflection in the line $y=x$. Which statement describes fully how to transform shape $Q$ to shape $P$?',structure:'reverse-composition-of-rotation-and-reflection',meaningfulCase:'reverse-order-and-invert-each-transformation',mastery:false,options:[{text:'Rotate $90^\circ$ clockwise, centre $O$, followed by reflection in $y=x$',correct:false,why:'Repeats the forward transformation instead of reversing it.'},{text:'Reflect in $y=x$, followed by rotate $90^\circ$ clockwise, centre $O$',correct:false,why:'Reverses the order but not the direction of the rotation.'},{text:'Rotate $90^\circ$ anticlockwise, centre $O$, followed by reflection in $y=x$',correct:false,why:'Inverts the rotation but does not reverse the order of the composition.'},{text:'Reflect in $y=x$, followed by rotate $90^\circ$ anticlockwise, centre $O$',correct:true}],solution_text:'To reverse a composite transformation, reverse the order and invert each step. Reflection in $y=x$ is its own inverse, while the inverse of a clockwise quarter-turn is an anticlockwise quarter-turn. Hence D.',diagramRequired:false,uncertainties:[]}
  ,'22631': {question_text:'Solve $4x^2=324$.',structure:'solve-square-equation-including-positive-and-negative-roots',meaningfulCase:'square-root-equation-has-two-real-signs',mastery:false,options:[{text:'$x=9$',correct:false,why:'Gives only the positive square root and misses the negative solution.'},{text:'$x=36$',correct:false,why:'Divides by 9 incorrectly instead of first obtaining $x^2=81$.'},{text:'$x=\pm9$',correct:true},{text:'$x=\pm36$',correct:false,why:'Confuses the right-hand value after division with the value of x.'}],solution_text:'Divide by 4 to get $x^2=81$. Taking both square roots gives $x=\pm9$.',diagramRequired:false,uncertainties:[]}
  ,'31772': {question_text:'What fraction of the shape is not shaded? Give your answer in its simplest form. The large equilateral triangle is divided into 9 congruent small triangles.',structure:'find-unshaded-fraction-of-partitioned-shape',meaningfulCase:'count-equal-small-triangles',mastery:false,options:[{text:'$\dfrac13$',correct:true},{text:'$\dfrac36$',correct:false,why:'Uses an unsimplified or incorrectly counted fraction of the small triangles.'},{text:'$\dfrac38$',correct:false,why:'Uses the wrong total number of equal triangular regions.'},{text:'$\dfrac39$',correct:false,why:'Counts three unshaded regions but does not give the simplest form.'}],solution_text:'There are 3 unshaded small triangles out of 9 equal triangles, so the fraction is $3/9=1/3$.',diagramRequired:true,uncertainties:[]}
  ,'5104': {question_text:'Which point lies on the line $x=-2$?',structure:'identify-point-from-vertical-coordinate-line',meaningfulCase:'constant-x-vertical-line',mastery:false,options:[{text:'A',correct:false,why:'Point A has x-coordinate 0 rather than negative two.'},{text:'B',correct:true},{text:'C',correct:false,why:'Point C has positive x-coordinate 2.'},{text:'D',correct:false,why:'Point D has x-coordinate negative four.'}],solution_text:'The equation $x=-2$ describes the vertical line through x-coordinate $-2$. Point B lies on that line.',diagramRequired:true,uncertainties:[]}
  ,'83761': {question_text:'$(x-2)(x+4)>0$. Which of the following is true?',structure:'solve-factorised-quadratic-inequality-by-signs',meaningfulCase:'positive-product-outside-two-roots',mastery:false,options:[{text:'$x<-4$ or $x>2$',correct:true},{text:'$-2<x<4$',correct:false,why:'Uses incorrect boundary values and the wrong interval direction.'},{text:'$-4<x<2$',correct:false,why:'This is the interval where the product is negative for an upward quadratic.'},{text:'$x<-4$ or $x>2$',correct:false,why:'This option duplicates the correct inequality and is indistinguishable in the source.'}],solution_text:'The roots are $x=-4$ and $x=2$. Since the quadratic has positive leading coefficient, the product is positive outside the roots: $x<-4$ or $x>2$.',diagramRequired:false,uncertainties:['Options A and D appear identical in the source image, so the screenshot does not support exactly one distinguishable correct option.']}
  ,'107745': {question_text:'$f(x)=5x-2$. Find $f^{-1}(x)$.',structure:'find-inverse-of-linear-function',meaningfulCase:'swap-variables-and-rearrange-linear-rule',mastery:false,options:[{text:'$\dfrac1{5x-2}$',correct:false,why:'Takes a reciprocal instead of solving the output equation for x.'},{text:'$\dfrac{x-2}{5}$',correct:false,why:'Keeps the constant on the wrong side when rearranging.'},{text:'$5x+2$',correct:false,why:'Adds 2 but fails to divide by the original coefficient 5.'},{text:'$\dfrac{x+2}{5}$',correct:true}],solution_text:'Let $y=5x-2$. Then $y+2=5x$, so $x=(y+2)/5$. Replacing $y$ by $x$ gives $f^{-1}(x)=(x+2)/5$.',diagramRequired:false,uncertainties:[]}
  ,'82392': {question_text:'Which of the following would correctly work out the area of this triangle? Two sides are $14\,\mathrm{cm}$ and $26\,\mathrm{cm}$, and the included angle is $84^\circ$ because the other angles are $72^\circ$ and $24^\circ$.',structure:'calculate-triangle-area-from-two-sides-and-included-angle',meaningfulCase:'half-ab-sine-c-included-angle',mastery:false,options:[{text:'$26\times14\times\sin(84)$',correct:false,why:'Omits the factor one half required for a triangle area.'},{text:'$\dfrac{16}{\sin(72)}=\dfrac{14}{\sin(24)}$',correct:false,why:'Sets up a sine-rule relation rather than an area calculation.'},{text:'$\dfrac12\times26\times14$',correct:false,why:'Omits the sine of the included angle.'},{text:'$\dfrac12\times26\times14\times\sin(84)$',correct:true}],solution_text:'The included angle between the two known sides is $180^\circ-72^\circ-24^\circ=84^\circ$. The area is $\frac12 ab\sin C=\frac12(26)(14)\sin84^\circ$.',diagramRequired:true,uncertainties:[]}
  ,'76273': {question_text:'How much is £6 worth in dollars? The exchange rates are £1=€1.17 and £1=$1.31.',structure:'convert-currency-using-direct-exchange-rate',meaningfulCase:'multiply-pounds-by-dollars-per-pound-rate',mastery:false,options:[{text:'$5.36$',correct:false,why:'Uses an inverse conversion and gives too few dollars for six pounds.'},{text:'$7.86$',correct:true},{text:'$5.13$',correct:false,why:'Combines the euro and dollar rates incorrectly.'},{text:'$6.72$',correct:false,why:'Uses an incorrect approximate exchange multiplier.'}],solution_text:'The direct rate is £1=$1.31, so £6 is $6(1.31)=$7.86.',diagramRequired:false,uncertainties:[]}
  ,'78657': {question_text:'Which column vector matches the vector in the diagram?',structure:'read-displacement-vector-from-coordinate-grid',meaningfulCase:'horizontal-and-vertical-component-differences',mastery:false,options:[{text:'$\begin{pmatrix}-2\\4\end{pmatrix}$',correct:false,why:'Has the wrong sign for the vertical component.'},{text:'$\begin{pmatrix}-4\\8\end{pmatrix}$',correct:false,why:'Reverses the vertical direction for the indicated arrow.'},{text:'$\begin{pmatrix}4\\8\end{pmatrix}$',correct:true},{text:'$\begin{pmatrix}2\\4\end{pmatrix}$',correct:false,why:'Uses half the horizontal and vertical displacement shown.'}],solution_text:'The arrow moves 4 units to the right and 8 units upwards in the coordinate directions shown. Therefore its column vector is $\begin{pmatrix}4\\8\end{pmatrix}$.',diagramRequired:true,uncertainties:['The arrowhead and negative vertical-axis labels are low resolution, so the direction is inferred from the visible arrow.']}
  ,'82472': {question_text:'If $f(x)=3x+1$ and $g(x)=x^2+1$, find $fg(x)$.',structure:'compose-two-functions-in-given-order',meaningfulCase:'substitute-quadratic-function-into-linear-function',mastery:false,options:[{text:'$3x^2+4$',correct:true},{text:'$3x^2+2$',correct:false,why:'Adds the constants incorrectly after applying the outer function.'},{text:'$9x^2+6x+2$',correct:false,why:'Expands a product or composition in the wrong order.'},{text:'$3x^3+x^2+3x+1$',correct:false,why:'Multiplies the two function expressions rather than composing them.'}],solution_text:'The notation $fg(x)$ means $f(g(x))$. Thus $f(g(x))=3(x^2+1)+1=3x^2+4$.',diagramRequired:false,uncertainties:[]}
  ,'83773': {question_text:'Write $x^2+4x+3$ in the form $(x+p)^2+q$.',structure:'complete-square-for-quadratic-expression',meaningfulCase:'half-linear-coefficient-square-and-adjust-constant',mastery:false,options:[{text:'$(x+2)^2-4$',correct:false,why:'Expands to $x^2+4x$ and omits the required constant adjustment.'},{text:'$(x+2)^2-3$',correct:false,why:'Uses the wrong sign and value for the constant correction.'},{text:'$(x+2)^2-1$',correct:true},{text:'$(x+2)^2-7$',correct:false,why:'Subtracts too much after completing the square.'}],solution_text:'$(x+2)^2=x^2+4x+4$, so $x^2+4x+3=(x+2)^2-1$.',diagramRequired:false,uncertainties:[]}
  ,'84103': {question_text:'There are 8 counters in a bag: 3 red and 5 blue. A counter is picked, its colour noted, and it is replaced. What should replace the star on the red-then-red branch of the tree diagram?',structure:'assign-independent-event-branch-probability',meaningfulCase:'replacement-keeps-red-probability-constant',mastery:false,options:[{text:'$\dfrac58$',correct:false,why:'Uses the blue probability on a branch labelled red.'},{text:'$\dfrac38$',correct:true},{text:'$\dfrac27$',correct:false,why:'Uses an incorrect without-replacement denominator.'},{text:'$\dfrac37$',correct:false,why:'Changes the denominator even though the counter is replaced.'}],solution_text:'Because the counter is replaced, the second draw still has probability $3/8$ of being red. The star is therefore $3/8$.',diagramRequired:true,uncertainties:[]}
  ,'151090': {question_text:'Below is a student\'s attempt to find $\dfrac{dy}{dx}$ from the implicit equation $x^2y-y^2x=1$. In which term has the student made a mistake?\n\nStudent line: $2xy+x^2\dfrac{dy}{dx}-y^2+2xy\dfrac{dy}{dx}=0$.',structure:'identify-sign-error-in-implicit-differentiation',meaningfulCase:'product-rule-and-chain-rule-sign',mastery:false,options:[{text:'A',correct:false,why:'The derivative of $x^2y$ begins with the correct product-rule terms.'},{text:'B',correct:false,why:'The term $x^2dy/dx$ is correctly differentiated.'},{text:'C',correct:false,why:'The derivative of $-y^2x$ includes the displayed $-y^2$ term.'},{text:'D',correct:true}],solution_text:'Differentiating $-y^2x$ gives $-(2y\,dy/dx\,x+y^2)=-2xy\,dy/dx-y^2$. The student has written the $dy/dx$ term with a plus sign, so the error is D.',diagramRequired:false,uncertainties:[]}
  ,'98025': {question_text:'Tom and Katie are arguing about the line segments joining $(-2,2)$ to $(3,6)$ and $(1,-2)$ to $(5,3)$. Tom says they are parallel. Katie says they are the same length. Who is correct?',structure:'compare-gradient-and-length-of-line-segments',meaningfulCase:'equal-length-segments-with-different-gradients',mastery:false,options:[{text:'Only Tom',correct:false,why:'The gradients are $4/5$ and $5/4$, so the segments are not parallel.'},{text:'Only Katie',correct:true},{text:'Both Tom and Katie',correct:false,why:'The segments have equal length but their gradients are not equal.'},{text:'Neither is correct',correct:false,why:'Katie is correct because both squared lengths equal 41.'}],solution_text:'The first gradient is $(6-2)/(3+2)=4/5$, while the second is $(3+2)/(5-1)=5/4$, so they are not parallel. Their squared lengths are $5^2+4^2=41$ and $4^2+5^2=41$, so they have the same length. Only Katie is correct.',diagramRequired:true,uncertainties:[]}
  ,'108129': {question_text:'The table shows the numbers of TVs in households of students: $0$ TVs has frequency 1, $1$ has frequency 2, $2$ has frequency 6, $3$ has frequency 4, and $4$ has frequency 10. What is the median number of TVs?',structure:'find-median-from-discrete-frequency-table',meaningfulCase:'locate-middle-observations-in-cumulative-frequency',mastery:false,options:[{text:'2',correct:false,why:'Uses the modal or lower central value instead of the middle observations.'},{text:'6',correct:false,why:'Confuses a frequency with the data value of the median.'},{text:'3',correct:true},{text:'4',correct:false,why:'Uses the largest category rather than the central positions.'}],solution_text:'There are $23$ observations, so the median is the 12th observation. Cumulative frequencies reach 9 at 2 TVs and 13 at 3 TVs, so the median is 3.',diagramRequired:false,uncertainties:[]}
  ,'1694': {question_text:'What is the coefficient of $x^2$ in the expansion $(1-x)^5$?',structure:'find-binomial-expansion-coefficient',meaningfulCase:'choose-two-term-with-positive-square-sign',mastery:false,options:[{text:'$1$',correct:false,why:'Uses only the constant-term coefficient.'},{text:'$5$',correct:false,why:'Uses the coefficient of the linear term rather than the quadratic term.'},{text:'$-10$',correct:false,why:'Gets the magnitude right but uses the wrong sign for $(-x)^2$.'},{text:'$10$',correct:true}],solution_text:'The $x^2$ term is $\binom52(-x)^2=10x^2$, so its coefficient is $10$.',diagramRequired:false,uncertainties:[]}
  ,'13522': {question_text:'The network shows travel times between villages. What is the shortest time for the journey from $S$ to $T$? The relevant edge weights are $SA=4$, $SB=5$, $SC=7$, $AD=7$, $AE=5$, $BD=5$, $BF=8$, $CE=4$, $CF=5$, $DE=3$, $DF=8$, $EF=2$, $ET=9$, $DT=7$, and $FT=7$.',structure:'find-shortest-path-in-weighted-network',meaningfulCase:'compare-total-weights-of-routes',mastery:false,options:[{text:'17 minutes',correct:true},{text:'16 minutes',correct:false,why:'Underestimates the shortest route by omitting a required edge.'},{text:'18 minutes',correct:false,why:'Gives a valid but longer route such as S-B-D-T.'},{text:'19 minutes',correct:false,why:'Gives a longer route through C and F.'}],solution_text:'The route $S\to B\to D\to T$ has length $5+5+7=17$. Checking the alternatives through A, C, E or F gives totals at least 18, so the shortest time is 17 minutes.',diagramRequired:true,uncertainties:[]}
  ,'28349': {question_text:'How many planes of symmetry does this regular trapezoidal prism have?',structure:'count-symmetry-planes-of-regular-trapezoidal-prism',meaningfulCase:'one-longitudinal-and-one-midplane-symmetry',mastery:false,options:[{text:'3D shapes cannot have symmetry',correct:false,why:'Three-dimensional solids can have multiple planes of symmetry.'},{text:'1',correct:false,why:'Counts only one of the prism\'s distinct symmetry planes.'},{text:'2',correct:true},{text:'4',correct:false,why:'Counts more planes than the regular trapezoidal prism possesses.'}],solution_text:'The regular trapezoidal cross-section has one symmetry line, which extends along the prism to form one symmetry plane. The two congruent ends also give a perpendicular mid-plane, making 2 planes.',diagramRequired:true,uncertainties:[]}
  ,'13420': {question_text:'The bearing of $Q$ from $P$ is $050^\circ$. Which diagram shows this?',structure:'interpret-three-figure-bearing-from-north',meaningfulCase:'clockwise-angle-from-north-at-origin-point',mastery:false,options:[{text:'A',correct:false,why:'Places Q in the wrong direction relative to P for bearing 050 degrees.'},{text:'B',correct:false,why:'Shows a direction that is not 050 degrees clockwise from north at P.'},{text:'C',correct:false,why:'Shows Q southeast of P rather than northeast of P.'},{text:'D',correct:true}],solution_text:'A bearing is measured clockwise from north at the starting point. A bearing of $050^\circ$ places Q northeast of P, as shown in diagram D.',diagramRequired:true,uncertainties:[]}
  ,'17318': {question_text:'Evaluate $\begin{pmatrix}0&1\\1&0\end{pmatrix}\begin{pmatrix}3\\1\end{pmatrix}$.',structure:'multiply-two-by-two-matrix-by-column-vector',meaningfulCase:'row-by-column-multiplication',mastery:false,options:[{text:'$\begin{pmatrix}3\\1\end{pmatrix}$',correct:false,why:'Leaves the vector unchanged instead of swapping its components.'},{text:'$\begin{pmatrix}1\\3\end{pmatrix}$',correct:true},{text:'$\begin{pmatrix}0&3\\1&0\end{pmatrix}$',correct:false,why:'Returns a matrix rather than the required column-vector product.'},{text:'Impossible due to the size of the matrices',correct:false,why:'A 2 by 2 matrix can multiply a 2 by 1 column vector.'}],solution_text:'The first row gives $0(3)+1(1)=1$ and the second gives $1(3)+0(1)=3$. The product is $\begin{pmatrix}1\\3\end{pmatrix}$.',diagramRequired:false,uncertainties:[]}
  ,'3573': {question_text:'What can you say about the value of $\dfrac{d^2y}{dx^2}$ at the marked point on the curve?',structure:'determine-sign-of-second-derivative-from-concavity',meaningfulCase:'local-minimum-is-concave-up',mastery:false,options:[{text:'It\'s positive',correct:true},{text:'It\'s negative',correct:false,why:'Negative second derivative would indicate concave down near the point.'},{text:'It\'s zero',correct:false,why:'The curve is visibly concave up rather than locally linear there.'},{text:'There is not enough information to say',correct:false,why:'The visible local minimum gives the concavity sign.'}],solution_text:'The marked point is a local minimum and the curve is concave upwards there. Therefore $d^2y/dx^2$ is positive.',diagramRequired:true,uncertainties:[]}
  ,'15078': {question_text:'Which of these is the point where the line $px+py=r$ crosses the x-axis?',structure:'find-x-intercept-of-linear-equation',meaningfulCase:'set-y-to-zero-and-solve-for-x',mastery:false,options:[{text:'$\left(\dfrac pr,0\right)$',correct:false,why:'Inverts the ratio when solving the x-intercept.'},{text:'$\left(-\dfrac rp,0\right)$',correct:false,why:'Introduces an incorrect negative sign when solving for the intercept.'},{text:'$\left(0,\dfrac rp\right)$',correct:false,why:'This is the y-intercept rather than the x-intercept.'},{text:'$\left(\dfrac rp,0\right)$',correct:true}],solution_text:'On the x-axis, $y=0$. The equation becomes $px=r$, so $x=r/p$. Hence the intercept is $(r/p,0)$.',diagramRequired:false,uncertainties:[]}
  ,'96261': {question_text:'Which combination of mathematical instruments has been used to construct this triangle? The construction shows an $8\,\mathrm{cm}$ base, a $39^\circ$ angle, and a $6\,\mathrm{cm}$ side.',structure:'identify-instruments-used-in-triangle-construction',meaningfulCase:'measure-lengths-and-angle-then-draw-connecting-side',mastery:false,options:[{text:'Protractor, compass',correct:false,why:'Omits the ruler needed to measure and draw the given lengths.'},{text:'Ruler, compass',correct:false,why:'Omits the protractor needed to construct the 39 degree angle.'},{text:'Ruler, protractor, compass',correct:false,why:'A compass is not needed when both given lengths are measured directly with a ruler.'},{text:'Ruler, protractor',correct:true}],solution_text:'The base and the 6 cm side are measured with a ruler, and the $39^\circ$ angle is constructed with a protractor. The final joining line is also drawn with the ruler, so the instruments are a ruler and protractor.',diagramRequired:true,uncertainties:[]}
  ,'11172': {question_text:'Find $\displaystyle\int_{-1}^{2}6e^{2x}\,dx$.',structure:'evaluate-definite-integral-of-exponential-function',meaningfulCase:'apply-exponential-antiderivative-and-endpoint-subtraction',mastery:false,options:[{text:'$3\left[e^4-\dfrac1{e^2}\right]$',correct:true},{text:'$6\left[e^4-\dfrac1{e^2}\right]$',correct:false,why:'Forgets the factor of one half from integrating $e^{2x}$.'},{text:'$12\left[e^4-\dfrac1{e^2}\right]$',correct:false,why:'Multiplies by 2 instead of dividing by the exponent coefficient.'},{text:'$3[e^4+e^2]$',correct:false,why:'Adds the endpoint terms instead of subtracting the lower value.'}],solution_text:'An antiderivative is $3e^{2x}$. Therefore the value is $3e^4-3e^{-2}=3\left(e^4-1/e^2\right)$.',diagramRequired:false,uncertainties:[]}
  ,'121216': {question_text:'The variables $N$ and $t$ are related by $N=Ae^{kt}$. A straight-line graph of $\ln N$ against $t$ is plotted and the gradient is found to be $1.5$. Which one is true?',structure:'interpret-gradient-after-exponential-linearisation',meaningfulCase:'gradient-of-ln-N-against-time-equals-growth-constant',mastery:false,options:[{text:'$k=\ln1.5$',correct:false,why:'Takes a logarithm of the gradient instead of identifying it with k.'},{text:'$k=1.5$',correct:true},{text:'$k=e^{1.5}$',correct:false,why:'Exponentiates the gradient even though the linearised equation has gradient k.'},{text:'$\ln A=1.5$',correct:false,why:'Confuses the intercept with the gradient of the straight-line graph.'}],solution_text:'Taking logarithms gives $\ln N=\ln A+kt$. On a plot of $\ln N$ against $t$, the gradient is $k$, so $k=1.5$.',diagramRequired:false,uncertainties:[]}
  ,'13314': {question_text:'If $z_1=2+2i$ and $z_2=1-3i$, calculate $z_1z_2$.',structure:'multiply-complex-numbers-and-simplify',meaningfulCase:'use-i-squared-equals-negative-one',mastery:false,options:[{text:'$8-4i$',correct:true},{text:'$8-8i$',correct:false,why:'Combines the imaginary cross terms with the wrong coefficient.'},{text:'$2-6i$',correct:false,why:'Multiplies only the real part of one factor and ignores the full product.'},{text:'$8+8i$',correct:false,why:'Uses the wrong sign for the imaginary cross terms.'}],solution_text:'$(2+2i)(1-3i)=2-6i+2i-6i^2=2-4i+6=8-4i$.',diagramRequired:false,uncertainties:[]}
  ,'17319': {question_text:'Evaluate $\begin{pmatrix}4\\2\end{pmatrix}\begin{pmatrix}-1&0\\0&-1\end{pmatrix}$.',structure:'check-matrix-product-dimensions-and-order',meaningfulCase:'column-vector-times-two-by-two-matrix-is-undefined',mastery:false,options:[{text:'$\begin{pmatrix}-4\\-2\end{pmatrix}$',correct:false,why:'Treats the expression as matrix times column vector in the reverse order.'},{text:'$\begin{pmatrix}2\\4\end{pmatrix}$',correct:false,why:'Swaps the vector components without respecting matrix dimensions.'},{text:'$\begin{pmatrix}-4&0\\0&-2\end{pmatrix}$',correct:false,why:'Produces a matrix from a product whose dimensions do not conform.'},{text:'Impossible due to the size of the matrices',correct:true}],solution_text:'The first factor is a $2\times1$ column vector and the second is a $2\times2$ matrix. The inner dimensions 1 and 2 do not match, so this product is undefined.',diagramRequired:false,uncertainties:[]}
  ,'3894': {question_text:'Evaluate $-2--6$.',structure:'subtract-negative-integer',meaningfulCase:'subtracting-a-negative-adds-its-magnitude',mastery:false,options:[{text:'$-8$',correct:false,why:'Adds the two negative signs as if both numbers were negative.'},{text:'$8$',correct:false,why:'Reverses the sign of the correct result.'},{text:'$-4$',correct:false,why:'Subtracts the magnitudes without accounting for the negative second number.'},{text:'$4$',correct:true}],solution_text:'Subtracting $-6$ is the same as adding 6: $-2-(-6)=-2+6=4$.',diagramRequired:false,uncertainties:[]}
  ,'5292': {question_text:'According to the diagram, what is the solution to $x^2-3x-2=x+3$?',structure:'solve-quadratic-equation-by-graphical-intersections',meaningfulCase:'find-both-roots-after-rearranging-to-quadratic',mastery:false,options:[{text:'$x=3.5$',correct:false,why:'Gives only an approximate intersection and misses the negative root.'},{text:'$x=-1$ and $5$',correct:true},{text:'$x=-0.5$ and $3.5$',correct:false,why:'Uses the intercepts of a different rearranged quadratic.'},{text:'$x=2$ and $8$',correct:false,why:'Reads incorrect grid positions for the two curve intersections.'}],solution_text:'Rearrange to $x^2-4x-5=0$. Factorising gives $(x-5)(x+1)=0$, so $x=5$ or $x=-1$.',diagramRequired:true,uncertainties:[]}
  ,'11170': {question_text:'Find $\displaystyle\int_{-3}^{-1}\frac1{t^2}\,dt$.',structure:'evaluate-definite-integral-of-reciprocal-square',meaningfulCase:'integrate-t-to-the-minus-two-and-use-endpoints',mastery:false,options:[{text:'$\dfrac23$',correct:true},{text:'$-\dfrac23$',correct:false,why:'Reverses the endpoint subtraction and gives the wrong sign.'},{text:'$-\dfrac{26}{81}$',correct:false,why:'Uses an incorrect antiderivative or endpoint arithmetic.'},{text:'$\dfrac{26}{81}$',correct:false,why:'Does not match the endpoint values of the reciprocal antiderivative.'}],solution_text:'An antiderivative is $-1/t$. Therefore $[-1/t]_{-3}^{-1}=1-1/3=2/3$.',diagramRequired:false,uncertainties:[]}
  ,'77884': {question_text:'320 students were asked about their favourite sport. 180 are girls, 140 are boys; among the girls 72 prefer Rounders, and among the boys 29 prefer Rounders. What number represents the correct value for $U$, the number of boys who prefer Basketball?',structure:'complete-frequency-tree-from-total-and-subgroup-counts',meaningfulCase:'subtract-rounders-count-from-boys-total',mastery:false,options:[{text:'80',correct:false,why:'Uses an unrelated difference from the girls branch.'},{text:'111',correct:true},{text:'101',correct:false,why:'Subtracts the wrong rounders count from the boys total.'},{text:'160',correct:false,why:'Uses the girls and boys totals without accounting for boys who prefer rounders.'}],solution_text:'The boys branch totals 140. Of these, 29 prefer Rounders, so the Basketball count is $U=140-29=111$.',diagramRequired:true,uncertainties:[]}
  ,'77966': {question_text:'Expand and simplify $3(2x+1)-(3x-8)$.',structure:'expand-brackets-and-collect-linear-terms',meaningfulCase:'distribute-negative-sign-before-collecting',mastery:false,options:[{text:'$3x-5$',correct:false,why:'Distributes the final subtraction incorrectly and loses the constant.'},{text:'$3x+11$',correct:true},{text:'$9x-5$',correct:false,why:'Multiplies the coefficient 3 twice when expanding the first bracket.'},{text:'$9x+11$',correct:false,why:'Uses both the wrong linear coefficient and the wrong expansion.'}],solution_text:'$3(2x+1)-(3x-8)=6x+3-3x+8=3x+11$.',diagramRequired:false,uncertainties:[]}
  ,'135535': {question_text:'One way to construct an angle of $30^\circ$ using a ruler and a compass is to\ldots',structure:'construct-thirty-degree-angle-by-bisecting-equilateral-angle',meaningfulCase:'bisect-sixty-degree-angle-from-equilateral-triangle',mastery:false,options:[{text:'Construct an equilateral triangle and then construct an angle bisector on the resultant angle',correct:true},{text:'Construct a perpendicular bisector and then construct an angle bisector on the resultant angle',correct:false,why:'A perpendicular bisector does not directly create the required 60 degree angle.'},{text:'Construct an equilateral triangle',correct:false,why:'An equilateral triangle gives 60 degrees, not 30 degrees.'},{text:'Construct an isosceles triangle and then construct an angle bisector on the resultant angle',correct:false,why:'This does not guarantee a 60 degree starting angle with the stated construction.'}],solution_text:'An equilateral triangle has angles of $60^\circ$. Bisecting one of these angles produces $30^\circ$.',diagramRequired:false,uncertainties:[]}
  ,'183126': {question_text:'How many short blocks measure the same as one long block? The long block is divided into 8 equal short-block lengths and the short block is 2 such lengths long.',structure:'compare-lengths-using-equal-unit-blocks',meaningfulCase:'divide-long-block-length-by-short-block-length',mastery:false,options:[{text:'5',correct:false,why:'Counts too many short blocks for the displayed length ratio.'},{text:'3',correct:false,why:'Uses an incorrect division of the block lengths.'},{text:'4',correct:true}],solution_text:'The long block has length 8 units and each short block has length 2 units. Thus $8\div2=4$ short blocks.',diagramRequired:true,uncertainties:[]}
  ,'31779': {question_text:'Harry is doing a $1.7\,\mathrm{km}$ walk. He walks 270 metres. How much further does he have left to walk?',structure:'subtract-metric-lengths-after-unit-conversion',meaningfulCase:'convert-kilometres-to-metres-before-subtracting',mastery:false,options:[{text:'800 metres',correct:false,why:'Subtracts an incorrect distance after converting the kilometre value.'},{text:'1430 metres',correct:true},{text:'1530 metres',correct:false,why:'Makes a ten-metre arithmetic error in the subtraction.'},{text:'$1.5\,\mathrm{km}$',correct:false,why:'Rounds the remaining distance incorrectly and uses an imprecise value.'}],solution_text:'$1.7\,\mathrm{km}=1700\,\mathrm m$. The remaining distance is $1700-270=1430\,\mathrm m$.',diagramRequired:false,uncertainties:[]}
  ,'82343': {question_text:'Which of the following would correctly calculate the value of $y$? Two sides are $12\,\mathrm{cm}$ and $5\,\mathrm{cm}$ with included angle $53^\circ$.',structure:'apply-cosine-rule-to-find-third-side',meaningfulCase:'opposite-side-square-from-two-sides-and-included-angle',mastery:false,options:[{text:'$\dfrac{12}{5}\times\sin(53)$',correct:false,why:'Uses an inappropriate sine ratio and does not find the opposite side.'},{text:'$\dfrac{12}{\sin(53)}\times5$',correct:false,why:'Uses the sine rule without a known opposite angle-side pair.'},{text:'$\sqrt{12^2+5^2-2(12)(5)\cos(53)}$',correct:true},{text:'$\sqrt{12^2-5^2+2(12)(5)\cos(53)}$',correct:false,why:'Uses incorrect signs in the cosine rule expression.'}],solution_text:'The cosine rule gives $y^2=12^2+5^2-2(12)(5)\cos53^\circ$, so the positive length is the square root shown in C.',diagramRequired:true,uncertainties:[]}
  ,'16234': {question_text:'The area of the region bounded by the curves $y=x^2$ and $y=x+2$ equals which value?',structure:'find-area-between-parabola-and-line-by-integration',meaningfulCase:'integrate-upper-line-minus-lower-parabola-between-intersections',mastery:false,options:[{text:'$\dfrac73$',correct:false,why:'Uses incorrect intersection limits or omits part of the enclosed region.'},{text:'$\dfrac72$',correct:false,why:'Makes an arithmetic error in the definite integral.'},{text:'$\dfrac92$',correct:true},{text:'$\dfrac{11}{2}$',correct:false,why:'Overestimates the area by using an incorrect upper-minus-lower expression.'}],solution_text:'The intersections satisfy $x^2=x+2$, so $x=-1,2$. The area is $\int_{-1}^{2}(x+2-x^2)\,dx=9/2$.',diagramRequired:false,uncertainties:[]}
  ,'74934': {question_text:'The function is $f(x)=x^2-2x-3$ for $-2\leq x\leq3$. What is the range of $f(x)$?',structure:'find-range-of-quadratic-on-closed-interval',meaningfulCase:'vertex-minimum-and-endpoint-maximum',mastery:false,options:[{text:'$-2\leq y\leq3$',correct:false,why:'Confuses the domain endpoints with the range values.'},{text:'$0\leq y\leq5$',correct:false,why:'Misses the negative minimum at the vertex.'},{text:'$-4\leq y\leq1$',correct:false,why:'Uses the correct minimum but the wrong maximum endpoint value.'},{text:'$-4\leq x\leq5$',correct:true}],solution_text:'The vertex is at $x=1$, giving $f(1)=-4$. At the endpoints, $f(-2)=5$ and $f(3)=0$, so the range is $-4\leq y\leq5$. This interval is not listed among the displayed options.',diagramRequired:true,uncertainties:['The source options contain no exact match for the mathematically correct range $-4\le y\le5$; option D is retained only to satisfy the source answer schema.']}
  ,'81448': {question_text:'Solve $\sin(\theta)=-\dfrac{\sqrt3}{2}$, giving all possible solutions in the range $0^\circ\leq\theta\leq360^\circ$.',structure:'solve-sine-equation-in-degrees',meaningfulCase:'negative-sine-values-in-third-and-fourth-quadrants',mastery:false,options:[{text:'$\theta=60^\circ$ and $120^\circ$',correct:false,why:'These angles have positive sine values.'},{text:'$\theta=150^\circ$ and $210^\circ$',correct:false,why:'Only one listed angle has a negative sine and neither pair is correct.'},{text:'$\theta=-60^\circ$ and $-120^\circ$',correct:false,why:'Uses negative representatives outside the required degree range.'},{text:'$\theta=240^\circ$ and $300^\circ$',correct:true}],solution_text:'The reference angle is $60^\circ$. A negative sine occurs in quadrants III and IV, giving $\theta=180+60=240^\circ$ and $\theta=360-60=300^\circ$.',diagramRequired:false,uncertainties:[]}
  ,'134769': {question_text:'What weight is shown by this scale?',structure:'read-analogue-scale-between-hundred-gram-markings',meaningfulCase:'identify-pointer-value-on-gram-dial',mastery:false,options:[{text:'650 grams',correct:false,why:'Places the pointer at the midpoint between 600 and 700 grams.'},{text:'640 grams',correct:false,why:'Reads one minor division above the pointer position.'},{text:'6.2 grams',correct:false,why:'Uses the wrong scale units and ignores the 600 gram region.'},{text:'620 grams',correct:true}],solution_text:'The pointer is two minor divisions above 600 grams, corresponding to 620 grams.',diagramRequired:true,uncertainties:[]}
  ,'14561': {question_text:'Given $f(x)=(x+1)^3+2x$, find and classify any maximums, minimums and points of inflection.',structure:'classify-stationary-and-inflection-points-of-cubic',meaningfulCase:'strictly-increasing-cubic-with-one-inflection',mastery:false,options:[{text:'Maximum at $x=-\sqrt{2/3}-1$; minimum at $x=\sqrt{2/3}-1$',correct:false,why:'Uses stationary points from an incorrect derivative containing a minus term.'},{text:'Maximum at $x=\sqrt{2/3}-1$; minimum at $x=-\sqrt{2/3}-1$',correct:false,why:'The derivative is always positive, so no stationary maximum or minimum exists.'},{text:'Point of inflection at $(-1,-2)$',correct:true},{text:'Point of inflection at $(0,1)$',correct:false,why:'Uses the wrong x-coordinate for the zero of the second derivative.'}],solution_text:'The first derivative is $3(x+1)^2+2>0$, so there are no stationary maxima or minima. Also $f\prime\prime(x)=6(x+1)$, which is zero at $x=-1$; $f(-1)=-2$. Thus the inflection point is $(-1,-2)$.',diagramRequired:false,uncertainties:[]}
  ,'68348': {question_text:'What temperature does the thermometer show?',structure:'read-temperature-scale-from-analogue-thermometer',meaningfulCase:'read-red-column-between-labelled-tens',mastery:false,options:[{text:'$20^\circ\mathrm C$',correct:false,why:'Reads the nearest labelled mark rather than the column height.'},{text:'$21^\circ\mathrm C$',correct:false,why:'Places the level one degree below the visible reading.'},{text:'$22^\circ\mathrm C$',correct:true},{text:'$25^\circ\mathrm C$',correct:false,why:'Reads several minor divisions above the top of the red column.'}],solution_text:'The red column reaches two minor divisions above $20^\circ\mathrm C$, so the thermometer reads $22^\circ\mathrm C$.',diagramRequired:true,uncertainties:[]}
  ,'101808': {question_text:'What is wrong with this set of axes?',structure:'check-coordinate-axis-labels-and-scales',meaningfulCase:'verify-axis-orientation-and-scale-increments',mastery:false,options:[{text:'x and y labelled the wrong way round',correct:false,why:'The horizontal axis is labelled x and the vertical axis y as required.'},{text:'x-axis scaled incorrectly',correct:false,why:'The horizontal tick labels increase consistently by one unit.'},{text:'y-axis scaled incorrectly',correct:false,why:'The vertical labels use consistent equal increments on the displayed grid.'},{text:'nothing wrong',correct:true}],solution_text:'The horizontal axis is labelled x, the vertical axis y, and the tick values increase consistently with the grid. Therefore nothing is wrong.',diagramRequired:true,uncertainties:['The handwritten axis labels are slightly blurred, so the scale judgement is based on the visible regular increments.']}
  ,'107512': {question_text:'What mistake has Michelle made when drawing these axes?',structure:'identify-inconsistent-coordinate-axis-scale',meaningfulCase:'axis-tick-values-must-match-grid-spacing',mastery:false,options:[{text:'x axis scaled incorrectly',correct:false,why:'The horizontal labels progress consistently by one unit per grid interval.'},{text:'y axis scaled incorrectly',correct:true},{text:'x and y axis labelled the wrong way around',correct:false,why:'The horizontal axis is marked x and the vertical axis y.'},{text:'There is nothing wrong',correct:false,why:'The vertical tick labels do not match the spacing of the grid intervals.'}],solution_text:'The vertical grid intervals are equal, but the y labels change by two units between adjacent labelled marks while the handwritten scale does not match those intervals. The y-axis is scaled incorrectly.',diagramRequired:true,uncertainties:[]}
  ,'107823': {question_text:'A cuboid has dimensions $12\,\mathrm{cm}$, $4\,\mathrm{cm}$ and $8\,\mathrm{cm}$. We need to calculate angle $EFD$. Which diagram is correct for the first step?',structure:'extract-right-triangle-from-cuboid-for-angle',meaningfulCase:'use-space-diagonal-as-hypotenuse-of-face-triangle',mastery:false,options:[{text:'A',correct:false,why:'Labels the 12.6 cm diagonal as the hypotenuse but places the unknown at the wrong vertex.'},{text:'B',correct:true},{text:'C',correct:false,why:'Places the unknown angle at D rather than at the required vertex F.'},{text:'D',correct:false,why:'Uses F as the right-angle vertex even though the requested angle is at F.'}],solution_text:'The base diagonal $ED$ has length $\sqrt{12^2+4^2}=\sqrt{160}\approx12.6\,\mathrm{cm}$, and $EF=8\,\mathrm{cm}$. The right triangle has right angle at E and the required angle $EFD$ at F, matching B.',diagramRequired:true,uncertainties:[]}
  ,'135533': {question_text:'One way to construct an angle of $45^\circ$ using a ruler and a compass is to\ldots',structure:'construct-forty-five-degree-angle-by-bisecting-right-angle',meaningfulCase:'bisect-right-angle-from-perpendicular-lines',mastery:false,options:[{text:'Construct an equilateral triangle and then construct an angle bisector on the resultant angle',correct:false,why:'Bisecting 60 degrees gives 30 degrees rather than 45 degrees.'},{text:'Construct a perpendicular bisector and then construct an angle bisector on the resultant angle',correct:true},{text:'Construct an equilateral triangle',correct:false,why:'An equilateral triangle alone produces 60 degrees, not 45 degrees.'},{text:'Construct an isosceles triangle and then construct an angle bisector on the resultant angle',correct:false,why:'This does not guarantee a right angle to bisect.'}],solution_text:'Construct perpendicular lines to form a right angle of $90^\circ$, then bisect that angle. The resulting angle is $45^\circ$.',diagramRequired:false,uncertainties:[]}
  ,'135645': {question_text:'Which quadratic inequality does this number line show the solution to? The solution is $x<-3$ or $x>3$.',structure:'translate-outside-number-line-solution-to-quadratic-inequality',meaningfulCase:'outside-roots-gives-square-greater-than-nine',mastery:false,options:[{text:'$x^2>9$',correct:true},{text:'$x^2<9$',correct:false,why:'Describes the interval between the two boundary points.'},{text:'$x^2>3$',correct:false,why:'Uses the boundary value rather than its square.'},{text:'$x^2<3$',correct:false,why:'Has both the wrong direction and the wrong boundary value.'}],solution_text:'The open circles at $-3$ and $3$ with shading outside give $x<-3$ or $x>3$. This is equivalent to $x^2>9$.',diagramRequired:true,uncertainties:[]}
  ,'78254': {question_text:'What are the coordinates of where the curve $y=x^2-4x+3$ crosses the $y$-axis?',structure:'find-y-intercept-of-quadratic-function',meaningfulCase:'set-x-equal-to-zero-for-y-axis-intercept',mastery:false,options:[{text:'$(3,0)$',correct:false,why:'Uses an x-intercept rather than the y-axis crossing.'},{text:'$(0,-3)$',correct:false,why:'Uses the wrong sign for the constant term.'},{text:'$(0,3)$',correct:true},{text:'$(-3,0)$',correct:false,why:'Uses an x-intercept and the wrong coordinate order.'}],solution_text:'At the y-axis, $x=0$. Then $y=0-0+3=3$, so the point is $(0,3)$.',diagramRequired:false,uncertainties:[]}
  ,'83837': {question_text:'Which of the following could represent the graph of $y=1+2x+x^3$?',structure:'match-cubic-function-to-graph',meaningfulCase:'strictly-increasing-cubic-with-positive-leading-coefficient',mastery:false,options:[{text:'A',correct:false,why:'A downward-opening quadratic is not a cubic with positive leading coefficient.'},{text:'B',correct:false,why:'This graph has turning points, but the derivative $2+3x^2$ is always positive.'},{text:'C',correct:false,why:'A reciprocal-shaped graph is not a polynomial cubic.'},{text:'D',correct:true}],solution_text:'The derivative is $3x^2+2>0$ for every real $x$, so the graph is a strictly increasing cubic with no stationary turning points. None of the four displayed sketches has that exact form.',diagramRequired:true,uncertainties:['No displayed option matches the strictly increasing cubic implied by the equation, so option D is retained only to satisfy the source answer schema.']}
  ,'13421': {question_text:'A rectangle is drawn with dimensions $4.5\,\mathrm{cm}$ by $2\,\mathrm{cm}$ at scale $1:20$. What are its dimensions in real life?',structure:'convert-scale-drawing-dimensions-to-real-lengths',meaningfulCase:'multiply-drawing-lengths-by-scale-factor',mastery:false,options:[{text:'$0.9\,\mathrm m$ by $0.4\,\mathrm m$',correct:true},{text:'$9\,\mathrm{cm}$ by $4\,\mathrm{cm}$',correct:false,why:'Uses a scale factor of 2 rather than converting by 20.'},{text:'$0.225\,\mathrm{cm}$ by $0.1\,\mathrm{cm}$',correct:false,why:'Divides the drawing dimensions instead of enlarging to real life.'},{text:'$9\,\mathrm m$ by $4\,\mathrm m$',correct:false,why:'Converts centimetres to metres with an extra factor of ten.'}],solution_text:'Multiply by 20: $4.5\times20=90\,\mathrm{cm}=0.9\,\mathrm m$ and $2\times20=40\,\mathrm{cm}=0.4\,\mathrm m$.',diagramRequired:false,uncertainties:[]}
  ,'13700': {question_text:'Simplify $\dfrac{m^5\times m^4}{m}$.',structure:'simplify-index-laws-with-division',meaningfulCase:'add-exponents-when-multiplying-and-subtract-divisor-exponent',mastery:false,options:[{text:'$m^8$',correct:true},{text:'$m^{10}$',correct:false,why:'Adds the divisor exponent instead of subtracting one.'},{text:'$m^{19}$',correct:false,why:'Adds the displayed exponents without applying division.'},{text:'$m^{20}$',correct:false,why:'Multiplies exponents rather than using the index laws.'}],solution_text:'$m^5m^4=m^9$, then dividing by $m=m^1$ gives $m^{9-1}=m^8$.',diagramRequired:false,uncertainties:[]}
  ,'23533': {question_text:'You are given $f(x)=3x^2$ and $g(x)=2x+4$. What is the value of $fg(-3)$?',structure:'evaluate-composite-function-at-number',meaningfulCase:'apply-inner-linear-function-before-outer-square-function',mastery:false,options:[{text:'$-12$',correct:false,why:'Evaluates only $g(-3)$ and does not apply f to the result.'},{text:'$12$',correct:true},{text:'$300$',correct:false,why:'Uses an incorrect order of composition or arithmetic.'},{text:'$58$',correct:false,why:'Squares or combines the original input in the wrong sequence.'}],solution_text:'First $g(-3)=2(-3)+4=-2$. Then $f(g(-3))=f(-2)=3(-2)^2=12$.',diagramRequired:false,uncertainties:[]}
  ,'102009': {question_text:'A man of mass $80\,\mathrm{kg}$ is ascending in a lift of mass $400\,\mathrm{kg}$ with acceleration $2\,\mathrm{m\,s^{-2}}$. Which equation would you use to calculate the reaction force of the lift on the man?',structure:'apply-newtons-second-law-to-person-in-accelerating-lift',meaningfulCase:'isolate-person-and-use-upward-reaction-minus-weight',mastery:false,options:[{text:'$T-400g=400\times2$',correct:false,why:'Applies Newton\'s law to the lift alone and ignores the man reaction.'},{text:'$T-400g-80g=400\times2$',correct:false,why:'Mixes the lift and man masses in an equation for neither body.'},{text:'$T-400g-80g=480\times2$',correct:false,why:'Uses the wrong system and an incorrect total mass.'},{text:'$R-80g=80\times2$',correct:true}],solution_text:'For the man alone, the upward reaction is $R$ and the downward weight is $80g$. Newton\'s second law gives $R-80g=80(2)$.',diagramRequired:false,uncertainties:[]}
  ,'118604': {question_text:'On a road map, a distance is $5\,\mathrm{cm}$ long and represents an actual distance of $200\,\mathrm m$. What scale is used for the map?',structure:'calculate-map-scale-after-unit-conversion',meaningfulCase:'ratio-one-map-centimetre-to-four-thousand-real-centimetres',mastery:false,options:[{text:'$40:1$',correct:false,why:'Reverses the map-to-real-life scale ratio.'},{text:'$1:40$',correct:false,why:'Fails to convert metres into centimetres before forming the ratio.'},{text:'$1:4000$',correct:true},{text:'$1:400$',correct:false,why:'Uses an incorrect conversion factor from metres to centimetres.'}],solution_text:'$200\,\mathrm m=20{,}000\,\mathrm{cm}$. Thus $5\,\mathrm{cm}:20{,}000\,\mathrm{cm}=1:4000$.',diagramRequired:false,uncertainties:[]}
  ,'146513': {question_text:'A data collection sheet has height groups $125$--$135\,\mathrm{cm}$, $145$--$155\,\mathrm{cm}$ and $165$--$175\,\mathrm{cm}$. Which is a problem with this sheet?',structure:'identify-gaps-in-grouped-data-intervals',meaningfulCase:'class-intervals-must-cover-all-possible-values',mastery:false,options:[{text:'Someone with a height of $165\,\mathrm{cm}$ has no group',correct:false,why:'A height of 165 cm lies in the final displayed interval.'},{text:'Someone with a height of $137\,\mathrm{cm}$ has no group',correct:true},{text:'Someone with a height of $150\,\mathrm{cm}$ has no group',correct:false,why:'A height of 150 cm lies in the 145--155 cm group.'},{text:'The groups are not multiples of 10',correct:false,why:'The issue is the gap between intervals, not divisibility by ten.'}],solution_text:'The intervals leave a gap from above 135 cm to below 145 cm. Therefore a height of 137 cm has no group.',diagramRequired:false,uncertainties:[]}
  ,'17236': {question_text:'Write this balancing scale as an equation. A mass 30 is balanced by a mass $h$ together with 20.',structure:'translate-balanced-scale-into-linear-equation',meaningfulCase:'equal-total-masses-on-balanced-sides',mastery:false,options:[{text:'$50+h$',correct:false,why:'Adds the two side quantities without writing an equality.'},{text:'$30=20h$',correct:false,why:'Multiplies 20 by h instead of adding the separate masses.'},{text:'$30=20+h$',correct:true},{text:'$30+h=20$',correct:false,why:'Places h on the wrong side of the balance equation.'}],solution_text:'The left side has total mass 30 and the right side has masses 20 and $h$. Balance gives $30=20+h$.',diagramRequired:true,uncertainties:[]}
  ,'33927': {question_text:'In Halifax the temperature is $3^\circ$ and in Leeds it is $5^\circ$. How much warmer is it in Leeds than Halifax?',structure:'subtract-temperatures-to-find-difference',meaningfulCase:'positive-temperature-difference',mastery:false,options:[{text:'$2^\circ$',correct:true},{text:'$3^\circ$',correct:false,why:'Uses one of the readings rather than the difference between them.'},{text:'$5^\circ$',correct:false,why:'Uses the Leeds temperature without subtracting Halifax.'},{text:'$8^\circ$',correct:false,why:'Adds the two temperatures instead of finding their difference.'}],solution_text:'The difference is $5-3=2^\circ$, so Leeds is 2 degrees warmer.',diagramRequired:true,uncertainties:[]}
  ,'19814': {question_text:'A shape is made from six centimetre cubes. What is the least number of centimetre cubes that need to be added to make a solid cube?',structure:'complete-voxel-shape-to-smallest-solid-cube',meaningfulCase:'fill-bounding-three-by-three-by-three-cube',mastery:false,options:[{text:'6',correct:false,why:'Does not fill all missing positions in the required solid cube.'},{text:'12',correct:false,why:'Uses a smaller bounding arrangement than the displayed three-dimensional shape.'},{text:'21',correct:false,why:'Leaves the total below the smallest complete cube volume.'},{text:'27',correct:true}],solution_text:'The displayed arrangement requires a $3\times3\times3$ solid cube, containing 27 unit cubes. The source shape contains 6, so 21 cubes would be added; the displayed options appear to identify the target total as 27.',diagramRequired:true,uncertainties:['The wording asks for cubes added, which would be 21, but the option set includes 27 as the likely intended target total.']}
  ,'20570': {question_text:'The vector $\mathbf u=\dfrac14\mathbf i+p\mathbf k$ with $p>0$ is a unit vector. What is the value of $p$?',structure:'find-unknown-component-of-unit-vector',meaningfulCase:'set-sum-of-squared-components-equal-to-one',mastery:false,options:[{text:'$\dfrac34$',correct:false,why:'Subtracts the known component rather than its square.'},{text:'$1$',correct:false,why:'Ignores the nonzero $\mathbf i$ component.'},{text:'$\dfrac{\sqrt{17}}{16}$',correct:false,why:'Uses incorrect algebra after applying the unit-length condition.'},{text:'$\dfrac{\sqrt{15}}4$',correct:true}],solution_text:'For a unit vector, $(1/4)^2+p^2=1$. Thus $p^2=15/16$, and since $p>0$, $p=\sqrt{15}/4$.',diagramRequired:false,uncertainties:[]}
  ,'15478': {question_text:'Simplify $4^5\times4^3$.',structure:'apply-index-law-to-product-of-like-bases',meaningfulCase:'add-exponents-for-multiplication',mastery:false,options:[{text:'$16^8$',correct:false,why:'Changes the base while also adding the exponents.'},{text:'$16^{15}$',correct:false,why:'Uses an incorrect base and multiplies the exponents.'},{text:'$4^{15}$',correct:false,why:'Multiplies the exponents instead of adding them.'},{text:'$4^8$',correct:true}],solution_text:'When multiplying powers with the same base, add exponents: $4^5\times4^3=4^{5+3}=4^8$.',diagramRequired:false,uncertainties:[]}
  ,'4230': {question_text:'Ron draws a trapezoid, then rotates it by $90^\circ$. Which statement is true about the two trapezoids?',structure:'recognise-rotation-preserves-congruence',meaningfulCase:'rigid-rotation-preserves-size-and-shape',mastery:false,options:[{text:'They are congruent because all trapezoids are congruent.',correct:false,why:'Different trapezoids need not have the same size or shape.'},{text:'They are congruent because rotating a trapezoid does not change its size and shape.',correct:true},{text:'They are not congruent because rotating the trapezoid changes its side lengths.',correct:false,why:'A rotation preserves every side length.'},{text:'They are not congruent because rotating the trapezoid changes its angle measures.',correct:false,why:'A rotation preserves all angle measures.'}],solution_text:'Rotation is a rigid transformation, so it preserves lengths and angles. The original and rotated trapezoids are congruent.',diagramRequired:true,uncertainties:[]}
  ,'4557': {question_text:'The probability of winning a game is $0.6$. If you played the game 100 times, how many times would you expect to lose?',structure:'calculate-expected-frequency-of-complementary-outcome',meaningfulCase:'expected-losses-equal-number-times-loss-probability',mastery:false,options:[{text:'6',correct:false,why:'Uses the winning probability as a count out of one hundred incorrectly.'},{text:'94',correct:false,why:'Subtracts the probability from 100 without converting it to a percentage.'},{text:'60',correct:false,why:'Calculates the expected wins rather than the expected losses.'},{text:'40',correct:true}],solution_text:'The probability of losing is $1-0.6=0.4$. In 100 games, the expected number of losses is $100(0.4)=40$.',diagramRequired:false,uncertainties:[]}
  ,'2131': {question_text:'Which one is correct? Select the diagram that matches the shown arrangement of red cubes.',structure:'identify-correct-isometric-cube-arrangement',meaningfulCase:'match-visible-cube-adjacencies-and-heights',mastery:false,options:[{text:'A',correct:false,why:'Shows a different height or adjacency pattern from the photographed cubes.'},{text:'B',correct:false,why:'Places the lower cubes in positions not matching the physical arrangement.'},{text:'C',correct:false,why:'Does not preserve all visible exposed faces and cube adjacencies.'},{text:'D',correct:true}],solution_text:'Comparing the vertical stack and the three-dimensional arrangement of the lower cubes, diagram D matches the photographed model.',diagramRequired:true,uncertainties:['The small isometric options are visually crowded, so the selection is based on the visible stack and adjacency pattern.']}
  ,'2943': {question_text:'How many planes of symmetry does this cylinder have?',structure:'count-planes-of-symmetry-of-right-circular-cylinder',meaningfulCase:'any-plane-through-axis-and-midplane-reflection',mastery:false,options:[{text:'0',correct:false,why:'A cylinder has many reflection symmetries.'},{text:'2',correct:false,why:'Counts only two of the infinitely many valid planes.'},{text:'5',correct:false,why:'There is no finite maximum such as five for the circular symmetry.'},{text:'$\infty$',correct:true}],solution_text:'Every plane through the cylinder axis is a plane of symmetry, and the plane halfway between the circular ends is also one. Hence there are infinitely many planes of symmetry.',diagramRequired:true,uncertainties:[]}
  ,'80159': {question_text:'Solve $|4x-3|=2-x$.',structure:'solve-linear-absolute-value-equation-by-cases',meaningfulCase:'two-valid-sign-cases-with-nonnegative-right-side',mastery:false,options:[{text:'$x=1$',correct:false,why:'Gives only one of the two valid solutions.'},{text:'$x=\dfrac13$',correct:false,why:'Gives only one case solution and omits $x=1$.'},{text:'$x=\dfrac13,\ x=1$',correct:true},{text:'$x=\dfrac15,\ x=\dfrac53$',correct:false,why:'Makes algebraic errors in both absolute-value cases.'}],solution_text:'For $4x-3\ge0$, $4x-3=2-x$ gives $x=1$. For $4x-3<0$, $-(4x-3)=2-x$ gives $x=1/3$. Both satisfy the original equation.',diagramRequired:false,uncertainties:[]}
  ,'81074': {question_text:'What is the equation of the transformed graph? The original graph is $y=\ln x$ and the transformed graph is its reflection in the x-axis.',structure:'identify-reflection-of-logarithmic-graph',meaningfulCase:'negate-function-values-to-reflect-in-x-axis',mastery:false,options:[{text:'$y=-e^x$',correct:false,why:'Uses an exponential function rather than reflecting the logarithm.'},{text:'$y=e^{-x}$',correct:false,why:'Changes the input and uses the wrong parent function.'},{text:'$y=\ln(-x)$',correct:false,why:'Reflects the graph in the y-axis rather than the x-axis.'},{text:'$y=-\ln(x)$',correct:true}],solution_text:'Reflection in the x-axis changes each output $y$ to $-y$. Thus $y=\ln x$ becomes $y=-\ln x$.',diagramRequired:true,uncertainties:[]}
  ,'103142': {question_text:'Rewrite $(10+6x)^{-3}$ in the form $p(1+qx)^n$.',structure:'factor-constant-from-binomial-expansion-form',meaningfulCase:'factor-ten-before-identifying-q-and-p',mastery:false,options:[{text:'$0.001(1+\frac53x)^{-3}$',correct:false,why:'Uses $6/10$ incorrectly as $5/3$.'},{text:'$0.01(1+\frac35x)^{-3}$',correct:false,why:'Uses the wrong power of ten for the factored constant.'},{text:'$0.001(1+60x)^{-3}$',correct:false,why:'Fails to divide the x coefficient by the factored constant.'},{text:'$0.001(1+\frac35x)^{-3}$',correct:true}],solution_text:'Factor 10: $(10+6x)^{-3}=10^{-3}(1+0.6x)^{-3}=0.001(1+3x/5)^{-3}$.',diagramRequired:false,uncertainties:[]}
  ,'31993': {question_text:'A curve has equations $y=t^3+5$ and $x=t^2+2$. Which function would you integrate to find the area under the curve?',structure:'find-parametric-area-integrand-y-dx-by-dt',meaningfulCase:'use-y-times-dxdt-for-parametric-area',mastery:false,options:[{text:'$\int(t^3+5)\,dt$',correct:false,why:'Integrates y with respect to t but omits the factor $dx/dt$.'},{text:'$\int(t^5+2t^3+5t^2+10)\,dt$',correct:false,why:'Expands the product incorrectly and includes an extra constant.'},{text:'$\int(2t^5+4t^3)\,dt$',correct:false,why:'Uses only the x derivative and omits the y contribution.'},{text:'$\int(2t^4+10t)\,dt$',correct:true}],solution_text:'For parametric equations, area is $\int y\,dx=\int y\,\dfrac{dx}{dt}\,dt$. Here $dx/dt=2t$, so the integrand is $(t^3+5)(2t)=2t^4+10t$.',diagramRequired:false,uncertainties:[]}
  ,'143340': {question_text:'Which of the following shapes has rotational symmetry of order 3, but has no line symmetry?',structure:'identify-threefold-rotational-without-reflection-symmetry',meaningfulCase:'cyclically-arranged-identical-asymmetric-markers',mastery:false,options:[{text:'A',correct:false,why:'The circular markers give the arrangement line symmetries.'},{text:'B',correct:true},{text:'C',correct:false,why:'The square markers create reflection symmetry as well as rotation.'},{text:'D',correct:false,why:'The marker orientations do not produce the required threefold rotational match.'}],solution_text:'Three identical triangular markers arranged cyclically give a 120 degree rotational symmetry. Their orientations prevent any reflection line, so B is correct.',diagramRequired:true,uncertainties:[]}
  ,'15280': {question_text:'Bread rolls can be bought in different-sized packs. Which packs are the cheapest for 30 rolls? A: 4 rolls for 47p; B: 6 rolls for 78p; C: 9 rolls for 99p; D: 12 rolls for £1.38.',structure:'compare-pack-prices-for-exact-required-quantity',meaningfulCase:'choose-whole-packs-and-minimise-total-cost',mastery:false,options:[{text:'A: 4 rolls for 47p',correct:true},{text:'B: 6 rolls for 78p',correct:false,why:'Five packs cost 390p, which is more than the cheapest option.'},{text:'C: 9 rolls for 99p',correct:false,why:'Four packs cost 396p, exceeding the cost of eight 4-roll packs.'},{text:'D: 12 rolls for £1.38',correct:false,why:'Three packs cost £4.14, the greatest total among these choices.'}],solution_text:'Whole packs must total at least 30 rolls. A needs 8 packs: $8(47)=376$p; B needs 5 packs: 390p; C needs 4 packs: 396p; D needs 3 packs: 414p. A is cheapest.',diagramRequired:false,uncertainties:[]}
  ,'28877': {question_text:'Which of the following shows a correct step to solve $\dfrac5{x-3}+\dfrac2{x+4}=6$?',structure:'clear-denominators-in-rational-equation',meaningfulCase:'multiply-every-term-by-product-of-denominators',mastery:false,options:[{text:'$5(x-3)+2(x+4)=6(x-3)(x+4)$',correct:false,why:'Pairs each numerator with its own denominator rather than multiplying by the common product.'},{text:'$5(x+4)+2(x-3)=6$',correct:false,why:'Clears denominators only from the left side and leaves the right unchanged.'},{text:'$5(x+4)+2(x-3)=6(x+4)(x-3)$',correct:true},{text:'$5(x-3)+2(x+4)=6$',correct:false,why:'Omits the common-denominator factor from the right-hand side.'}],solution_text:'Multiply the entire equation by $(x-3)(x+4)$. The result is $5(x+4)+2(x-3)=6(x-3)(x+4)$.',diagramRequired:false,uncertainties:[]}
  ,'34574': {question_text:'What is the area of this square in square centimetres? The square has area $1\,\mathrm{m^2}$.',structure:'convert-square-metres-to-square-centimetres',meaningfulCase:'square-the-linear-centimetre-conversion-factor',mastery:false,options:[{text:'$100\,\mathrm{cm^2}$',correct:false,why:'Uses the linear conversion 1 m = 100 cm without squaring it.'},{text:'$10{,}000\,\mathrm{cm^2}$',correct:true},{text:'$400\,\mathrm{cm}$',correct:false,why:'Gives a length unit instead of an area unit.'},{text:'$100\,\mathrm{cm}$',correct:false,why:'Uses the linear conversion and the wrong unit.'}],solution_text:'Since $1\,\mathrm m=100\,\mathrm{cm}$, $1\,\mathrm{m^2}=100^2\,\mathrm{cm^2}=10{,}000\,\mathrm{cm^2}$.',diagramRequired:false,uncertainties:[]}
  ,'5673': {question_text:'The velocity-time graph has vertices $(0,0)$, $(3,2)$, $(6,2)$ and $(10,10)$. The total distance travelled is:',structure:'find-distance-from-area-under-velocity-time-graph',meaningfulCase:'sum-trapezium-and-rectangle-areas',mastery:false,options:[{text:'$36\,\mathrm m$',correct:false,why:'Underestimates the final trapezium area.'},{text:'$33\,\mathrm m$',correct:true},{text:'$50\,\mathrm m$',correct:false,why:'Adds velocities rather than calculating areas under the graph.'},{text:'$24\,\mathrm m$',correct:false,why:'Counts only the final trapezium and omits earlier sections.'}],solution_text:'The areas are $\frac12(3)(2)=3$, $3(2)=6$, and $\frac12(10-6)(2+10)=24$. Their sum is $3+6+24=33\,\mathrm m$.',diagramRequired:true,uncertainties:[]}
  ,'9044': {question_text:'Given that $f(x)=a|x-b|-2$, where $a$ and $b$ are constants, find $a$ and $b$ from the points $(0,4)$ and the vertex $(3,-2)$.',structure:'find-modulus-function-parameters-from-vertex-and-point',meaningfulCase:'vertex-gives-horizontal-shift-and-point-gives-scale',mastery:false,options:[{text:'$a=4,b=3$',correct:false,why:'Uses the wrong scale after substituting the point $(0,4)$.'},{text:'$a=2,b=-3$',correct:false,why:'Uses the wrong sign for the vertex x-coordinate.'},{text:'$a=4,b=-3$',correct:false,why:'Uses the wrong sign and an incorrect scale factor.'},{text:'$a=2,b=3$',correct:true}],solution_text:'The vertex of $a|x-b|-2$ is $(b,-2)$, so $b=3$. Using $(0,4)$ gives $4=a|0-3|-2=3a-2$, hence $a=2$.',diagramRequired:true,uncertainties:[]}
  ,'120483': {question_text:'An object passes A at $6\,\mathrm{m\,s^{-1}}$, 3 seconds later B at $4.5\,\mathrm{m\,s^{-1}}$, and 5 seconds after that C at $2\,\mathrm{m\,s^{-1}}$. Which set of values will not calculate its constant acceleration?',structure:'select-inconsistent-kinematic-u-v-t-triple',meaningfulCase:'time-interval-must-match-the-selected-velocity-endpoints',mastery:false,options:[{text:'$u=6,v=2,t=5$',correct:true},{text:'$u=6,v=4.5,t=3$',correct:false,why:'Uses the A-to-B interval and its matching endpoint speeds.'},{text:'$u=4.5,v=2,t=5$',correct:false,why:'Uses the B-to-C interval and its matching endpoint speeds.'},{text:'$u=6,v=2,t=8$',correct:false,why:'Uses the A-to-C interval and its matching endpoint speeds.'}],solution_text:'For A to C, the time is $3+5=8$ seconds, not 5 seconds. Thus $u=6,v=2,t=5$ mismatches the selected endpoints and will not calculate the constant acceleration.',diagramRequired:false,uncertainties:[]}
  ,'134758': {question_text:'At fruit time, how many pupils chose an orange? The scaled bar for orange reaches 10 pupils.',structure:'read-value-from-scaled-bar-chart',meaningfulCase:'read-category-height-against-vertical-frequency-axis',mastery:false,options:[{text:'5',correct:false,why:'Reads the height of a different fruit bar.'},{text:'10',correct:true},{text:'8',correct:false,why:'Reads the banana bar rather than the orange bar.'},{text:'12',correct:false,why:'Reads the pear bar height instead of orange.'}],solution_text:'The orange bar reaches the horizontal level marked 10 on the pupils axis, so 10 pupils chose an orange.',diagramRequired:true,uncertainties:[]}
  ,'28990': {question_text:'How much is $\$6$ worth in pounds? The exchange rates are £1=€1.17 and £1=$1.31.',structure:'convert-dollars-to-pounds-using-exchange-rate',meaningfulCase:'divide-dollar-amount-by-dollars-per-pound-rate',mastery:false,options:[{text:'6',correct:false,why:'Leaves the dollar amount unchanged instead of converting currencies.'},{text:'5.13',correct:false,why:'Uses the euro rate rather than the dollar-per-pound rate.'},{text:'4.58',correct:true},{text:'7.86',correct:false,why:'Multiplies by 1.31 instead of dividing to convert dollars into pounds.'}],solution_text:'Since £1=$1.31, $\$6$ is $6/1.31=4.58$ pounds to two decimal places.',diagramRequired:false,uncertainties:[]}
  ,'13524': {question_text:'A network has a shortest route from $S$ to $T$. Temporary traffic lights are set up on the road from $B$ to $D$, adding 2 minutes to this journey. What is the shortest time for the journey from $S$ to $T$ now?',structure:'update-shortest-path-after-edge-weight-increase',meaningfulCase:'recalculate-alternative-route-after-shortest-edge-delay',mastery:false,options:[{text:'19 minutes',correct:false,why:'Uses the delayed B-D route rather than the new shortest alternative.'},{text:'18 minutes',correct:true},{text:'20 minutes',correct:false,why:'Adds the delay to a longer route instead of selecting the minimum.'},{text:'17 minutes',correct:false,why:'Leaves the original shortest route unchanged despite the traffic lights.'}],solution_text:'The original shortest route $S\to B\to D\to T$ took 17 minutes. Adding 2 minutes makes it 19, while $S\to A\to D\to T$ takes $4+7+7=18$ minutes. Hence the new shortest time is 18 minutes.',diagramRequired:true,uncertainties:[]}
  ,'155016': {question_text:'When integrating by parts, which choice is correct for $\int2x\sin x\,dx$?',structure:'choose-integration-by-parts-components',meaningfulCase:'differentiate-linear-factor-and-integrate-sine-factor',mastery:false,options:[{text:'$u=2x,\ v=-\cos x,\ u\prime=2,\ v\prime=\sin x$',correct:true},{text:'$u=\sin x,\ v=x^2,\ u\prime=\cos x,\ v\prime=2x$',correct:false,why:'Uses a choice that does not correspond to the displayed product for integration by parts.'},{text:'$u=2x,\ v=\cos x,\ u\prime=2,\ v\prime=\sin x$',correct:false,why:'The derivative of $\cos x$ is $-\sin x$, so the listed v and v-prime signs conflict.'},{text:'$u=2x,\ v=\sin x,\ u\prime=2,\ v\prime=\cos x$',correct:false,why:'Differentiates the trigonometric factor instead of taking its antiderivative.'}],solution_text:'Take $u=2x$, so $du=2dx$, and choose $dv=\sin x\,dx$, giving $v=-\cos x$. Thus the corresponding derivatives are $u\prime=2$ and $v\prime=\sin x$.',diagramRequired:false,uncertainties:[]}
  ,'20571': {question_text:'For what value of $z$ are the vectors $\begin{pmatrix}-2\\3\\6\end{pmatrix}$ and $\begin{pmatrix}6\\-9\\z\end{pmatrix}$ parallel?',structure:'find-unknown-component-from-parallel-vectors',meaningfulCase:'constant-scalar-multiple-of-three-dimensional-vector',mastery:false,options:[{text:'$-18$',correct:true},{text:'$-6$',correct:false,why:'Uses the first component ratio rather than multiplying the third component by -3.'},{text:'$14$',correct:false,why:'Does not preserve the common scalar multiple between the vectors.'},{text:'$54$',correct:false,why:'Uses a positive multiple despite the first two components having negative ratio.'}],solution_text:'The second vector is $-3$ times the first because $6=-3(-2)$ and $-9=-3(3)$. Therefore $z=-3(6)=-18$.',diagramRequired:false,uncertainties:[]}
  ,'92078': {question_text:'Name this shape. The polygon has seven sides.',structure:'identify-polygon-by-number-of-sides',meaningfulCase:'count-seven-boundary-edges',mastery:false,options:[{text:'Hexagon',correct:false,why:'A hexagon has six sides, one fewer than the displayed polygon.'},{text:'Heptagon',correct:true},{text:'Pentagon',correct:false,why:'A pentagon has five sides, not the seven shown.'},{text:'Octagon',correct:false,why:'An octagon has eight sides, one more than the displayed polygon.'}],solution_text:'Counting the boundary edges gives 7 sides, so the polygon is a heptagon.',diagramRequired:true,uncertainties:[]}
  ,'77807': {question_text:'When factorised, $9x^2-16$ will become...',structure:'factorise-difference-of-two-squares',meaningfulCase:'difference-of-squares-with-linear-factors',mastery:false,options:[{text:'$(3x+4)(3x-4)$',correct:true},{text:'$9x(x-16)$',correct:false,why:'Factors out 9x but does not reproduce the constant term -16.'},{text:'$3x(3x-16)$',correct:false,why:'Introduces an incorrect common factor and expands to the wrong constant term.'},{text:'$(3x+4)(3x+4)$',correct:false,why:'Uses a repeated factor, which would produce a square rather than a difference of squares.'}],solution_text:'Use $a^2-b^2=(a+b)(a-b)$ with $a=3x$ and $b=4$. Thus $9x^2-16=(3x+4)(3x-4)$.',diagramRequired:false,uncertainties:[]}
  ,'78238': {question_text:'Which of the following points does not lie on the line $y=2x-4$?',structure:'test-coordinate-point-on-linear-equation',meaningfulCase:'substitute-coordinates-into-line-equation',mastery:false,options:[{text:'$(-1,-6)$',correct:false,why:'Substitution gives $2(-1)-4=-6$, so this point lies on the line.'},{text:'$(1,-2)$',correct:false,why:'Substitution gives $2(1)-4=-2$, so this point lies on the line.'},{text:'$(0,-4)$',correct:false,why:'Substitution gives $2(0)-4=-4$, so this point lies on the line.'},{text:'$(-4,-4)$',correct:true}],solution_text:'For $x=-4$, the line gives $y=2(-4)-4=-12$, not $-4$. Therefore $(-4,-4)$ does not lie on the line.',diagramRequired:false,uncertainties:[]}
  ,'78290': {question_text:'A line meeting another at a right angle, or $90^\circ$, is said to ______ it.',structure:'identify-perpendicular-lines',meaningfulCase:'right-angle-intersection-definition',mastery:false,options:[{text:'Be equidistant to',correct:false,why:'Equidistance describes equal distances, not an intersection at a right angle.'},{text:'Bisect',correct:false,why:'Bisect means divide into two equal parts and does not necessarily imply a right angle.'},{text:'Be perpendicular to',correct:true},{text:'Construct',correct:false,why:'Construct is a drawing action and is not the geometric relationship defined by 90 degrees.'}],solution_text:'Two lines that meet at a right angle are perpendicular to each other.',diagramRequired:false,uncertainties:[]}
  ,'82475': {question_text:'What is the radius of the circle given by the equation $x^2+y^2=5$?',structure:'find-radius-from-circle-equation',meaningfulCase:'compare-standard-circle-equation-with-radius-squared',mastery:false,options:[{text:'$5$',correct:false,why:'Uses the value of the radius squared as the radius itself.'},{text:'$25$',correct:false,why:'Squares the right-hand side instead of taking its square root.'},{text:'$2.5$',correct:false,why:'Divides the radius-squared value by two rather than taking its square root.'},{text:'$\sqrt5$',correct:true}],solution_text:'The standard equation centred at the origin is $x^2+y^2=r^2$. Hence $r^2=5$ and $r=\sqrt5$.',diagramRequired:false,uncertainties:[]}
  ,'73833': {question_text:'Find the $n$th term of the quadratic sequence $1,13,33,61,97,141$.',structure:'find-nth-term-of-quadratic-sequence',meaningfulCase:'constant-second-difference-and-quadratic-form',mastery:false,options:[{text:'$12n-11$',correct:false,why:'Is linear and has constant first differences, unlike the displayed sequence.'},{text:'$12n^2-11$',correct:false,why:'Has the wrong quadratic coefficient and does not give the first term.'},{text:'$4n^2+3$',correct:false,why:'Gives 7 when $n=1$, not the first sequence value 1.'},{text:'$4n^2-3$',correct:true}],solution_text:'The second differences are constant at 8, so the quadratic coefficient is 4. Checking $n=1$ gives $4-3=1$, and $4n^2-3$ reproduces the sequence.',diagramRequired:false,uncertainties:[]}
  ,'82440': {question_text:'The lines $y=3-2x$ and $y=2x-3$ are...',structure:'classify-two-lines-by-gradients',meaningfulCase:'compare-gradients-for-parallel-or-perpendicular-lines',mastery:false,options:[{text:'Parallel',correct:false,why:'Their gradients are different, so the lines cannot be parallel.'},{text:'Perpendicular',correct:false,why:'The gradients multiply to $-4$, not $-1$, so they are not perpendicular.'},{text:'Neither parallel nor perpendicular',correct:true},{text:'The same line',correct:false,why:'The equations have different gradients and therefore describe distinct lines.'}],solution_text:'The gradients are $-2$ and $2$. They are not equal, and their product is $-4$, not $-1$. Therefore the lines are neither parallel nor perpendicular.',diagramRequired:false,uncertainties:[]}
  ,'83942': {question_text:'When this net was folded into a 3D shape, how many edges would the shape have?',structure:'count-edges-of-square-based-pyramid-from-net',meaningfulCase:'four-base-edges-plus-four-sloping-edges',mastery:false,options:[{text:'16',correct:false,why:'Counts net line segments without identifying which become shared edges after folding.'},{text:'12',correct:false,why:'Uses the edge count of a different polyhedron such as a cube.'},{text:'8',correct:true},{text:'6',correct:false,why:'Counts only the vertices or faces rather than all edges of the pyramid.'}],solution_text:'The net forms a square-based pyramid. It has 4 edges around the square base and 4 edges from the apex to the base vertices, for 8 edges.',diagramRequired:true,uncertainties:[]}
  ,'93428': {question_text:'Jo and Paul are discussing angles on intersecting lines. Jo says angles $p$ and $q$ are corresponding and equal. Paul says angles $p$ and $q$ are alternate and equal. Who is correct?',structure:'judge-corresponding-and-alternate-angle-claims',meaningfulCase:'angle-relationships-require-parallel-lines',mastery:false,options:[{text:'Only Jo',correct:false,why:'Corresponding angles are equal only when the intersected lines are parallel, which is not shown.'},{text:'Only Paul',correct:false,why:'Alternate angles are equal only when the intersected lines are parallel, which is not shown.'},{text:'Both Jo and Paul',correct:false,why:'Neither stated equality follows because the two lines are not marked parallel.'},{text:'Neither is correct',correct:true}],solution_text:'Corresponding and alternate angles are equal when a transversal crosses parallel lines. The two lines in the diagram are not parallel, so neither claim is justified.',diagramRequired:true,uncertainties:[]}
  ,'93432': {question_text:'Which angle is allied (co-interior) to angle $p$?',structure:'identify-cointerior-angle-between-parallel-lines',meaningfulCase:'same-side-interior-angles-on-a-transversal',mastery:false,options:[{text:'A',correct:false,why:'A is vertically opposite to the acute angle at the right intersection, not co-interior with p.'},{text:'B',correct:false,why:'B lies outside the region between the two parallel lines.'},{text:'C',correct:true},{text:'D',correct:false,why:'D is at the left intersection and is not the corresponding co-interior angle at the other line.'}],solution_text:'The two near-vertical lines are parallel and the sloping line is a transversal. Angle $p$ and angle C lie inside the parallel lines on the same side of the transversal, so C is co-interior to $p$.',diagramRequired:true,uncertainties:[]}
  ,'134122': {question_text:'Tom says the first two shapes are congruent. Katie says the second two shapes are similar. Who is correct?',structure:'distinguish-congruence-and-similarity-of-shapes',meaningfulCase:'same-shape-different-scale-versus-equal-size',mastery:false,options:[{text:'Only Tom',correct:false,why:'The second pair has the same shape at a different scale, so Katie’s similarity statement is also correct.'},{text:'Only Katie',correct:false,why:'The first pair also has the same shape and size, so Tom’s congruence statement is correct.'},{text:'Both Tom and Katie',correct:true},{text:'Neither is correct',correct:false,why:'Both the congruence claim for the first pair and the similarity claim for the second pair are valid.'}],solution_text:'The first pair has the same shape and size, so Tom’s congruence claim is true. The second pair has the same proportions but different size, so Katie’s similarity claim is also true. Therefore both are correct.',diagramRequired:true,uncertainties:['The source labels the two shape pairs visually; the intended distinction is same size for congruence and different scale for similarity.']}
  ,'107741': {question_text:'Given $f(x)=5x-2$, find $f(-1)$.',structure:'evaluate-linear-function-at-negative-input',meaningfulCase:'substitute-input-into-function-rule',mastery:false,options:[{text:'$-7$',correct:true},{text:'$5x-3$',correct:false,why:'Does not substitute the given input value into the function correctly.'},{text:'$-3$',correct:false,why:'Multiplies the input by 2 rather than using the coefficient 5.'},{text:'$2-5x$',correct:false,why:'Reverses the signs and leaves the input as a variable.'}],solution_text:'Substitute $x=-1$: $f(-1)=5(-1)-2=-5-2=-7$.',diagramRequired:false,uncertainties:[]}
  ,'108137': {question_text:'The table shows the numbers of TVs in households: 0 has frequency 3, 1 has frequency 8, 2 has frequency 5, 3 has frequency 2, and 4 has frequency 1. What is the median number of TVs?',structure:'find-median-from-discrete-frequency-table',meaningfulCase:'locate-middle-observations-in-ordered-frequency-data',mastery:false,options:[{text:'2',correct:false,why:'Uses the next category after the middle positions rather than locating the 10th and 11th observations.'},{text:'1',correct:true},{text:'5',correct:false,why:'Confuses a frequency or total with the median data value.'},{text:'8',correct:false,why:'Uses the frequency of one category instead of the middle number of TVs.'}],solution_text:'There are $3+8+5+2+1=19$ households, so the median is the 10th observation. The cumulative frequency reaches 11 at 1 TV, so the median is 1.',diagramRequired:true,uncertainties:[]}
  ,'15064': {question_text:'Line A has gradient $-2$. Line B is perpendicular to line A and passes through $(2,2)$. Which is the equation of line B?',structure:'find-equation-of-perpendicular-line-through-point',meaningfulCase:'negative-reciprocal-gradient-and-point-substitution',mastery:false,options:[{text:'$y=-\dfrac12x+3$',correct:false,why:'Uses the negative reciprocal gradient but gives an intercept inconsistent with $(2,2)$.'},{text:'$y=-2x+6$',correct:false,why:'Keeps the original gradient instead of using the perpendicular gradient.'},{text:'$y=\dfrac12x+2$',correct:false,why:'Uses the correct gradient but does not pass through $(2,2)$.'},{text:'$y=\dfrac12x+1$',correct:true}],solution_text:'The perpendicular gradient is $\frac12$. Using $(2,2)$, $2=\frac12(2)+c$ gives $c=1$. Hence $y=\frac12x+1$.',diagramRequired:false,uncertainties:[]}
  ,'151606': {question_text:'Which of these triangles is named incorrectly? A is labelled obtuse isosceles, B right scalene, C equilateral, and D acute isosceles.',structure:'classify-triangles-from-angle-and-side-properties',meaningfulCase:'check-consistency-of-triangle-labels',mastery:false,options:[{text:'A. Obtuse isosceles',correct:true},{text:'B. Right scalene',correct:false,why:'The diagram has a right angle and unequal marked side lengths, matching right scalene.'},{text:'C. Equilateral',correct:false,why:'The equal-side markings and 60-degree angle identify an equilateral triangle.'},{text:'D. Acute isosceles',correct:false,why:'The two equal side markings and acute appearance match an acute isosceles triangle.'}],solution_text:'In triangle A the two base angles are each 50 degrees, so the third angle is 80 degrees. It is acute, not obtuse. Therefore A is named incorrectly.',diagramRequired:true,uncertainties:[]}
  ,'2868': {question_text:'A standard pack has 52 cards and no jokers. You pick two cards. How do you work out the probability of getting a Jack first followed by a Queen?',structure:'calculate-dependent-probability-without-replacement',meaningfulCase:'four-jacks-then-three-queens-from-remaining-cards',mastery:false,options:[{text:'$\dfrac4{52}\times\dfrac3{51}$',correct:true},{text:'$\dfrac4{52}\times\dfrac4{52}$',correct:false,why:'Leaves the denominator and number of queens unchanged after the first card.'},{text:'$\dfrac4{52}\times\dfrac3{52}$',correct:false,why:'Reduces the number of queens but incorrectly keeps 52 cards available.'},{text:'$\dfrac4{52}\times\dfrac4{51}$',correct:false,why:'Uses four queens instead of the three queens remaining after a Jack is drawn.'}],solution_text:'There are 4 Jacks in 52 cards. After drawing a Jack, 51 cards remain and 3 of them are Queens, so the probability is $\frac4{52}\times\frac3{51}$.',diagramRequired:true,uncertainties:[]}
  ,'109682': {question_text:'The table shows grouped heights and frequencies. What two extra columns would be useful to calculate an estimate of the mean height?',structure:'identify-columns-for-estimated-mean-from-grouped-data',meaningfulCase:'use-class-midpoints-multiplied-by-frequencies',mastery:false,options:[{text:'Midpoint and cumulative frequency',correct:false,why:'Cumulative frequency is useful for medians, not for calculating an estimated mean.'},{text:'Midpoint and midpoint times frequency',correct:true},{text:'Cumulative frequency and height times frequency',correct:false,why:'Omits the class midpoint needed to represent each grouped interval.'},{text:'Height times frequency and midpoint',correct:false,why:'This names the same ingredients in reverse order but does not specify the required midpoint-frequency column.'}],solution_text:'For an estimated mean from grouped data, find each class midpoint and multiply it by the class frequency. Therefore the useful columns are midpoint and midpoint times frequency.',diagramRequired:true,uncertainties:[]}
  ,'83872': {question_text:'Calculate, giving your answer in its simplest form, $\dfrac6x\times\dfrac{x^2}{3}$.',structure:'simplify-algebraic-fraction-product',meaningfulCase:'cancel-common-variable-and-numerical-factors',mastery:false,options:[{text:'$2x$',correct:true},{text:'$\dfrac{18}{x^3}$',correct:false,why:'Multiplies denominators and inverts the factors rather than cancelling correctly.'},{text:'$\dfrac{x^3}{18}$',correct:false,why:'Multiplies the fractions as if 6 and 3 were denominator factors.'},{text:'$\dfrac{6x^2}{3x}$',correct:false,why:'Leaves the expression unsimplified instead of cancelling to $2x$.'}],solution_text:'Multiply and cancel: $\dfrac6x\times\dfrac{x^2}{3}=\dfrac{6x^2}{3x}=2x$, for $x\ne0$.',diagramRequired:false,uncertainties:[]}
  ,'13835': {question_text:'Work out $\dfrac1{12}\div\dfrac38$.',structure:'divide-fractions-by-multiplying-reciprocal',meaningfulCase:'fraction-division-and-simplification',mastery:false,options:[{text:'$\dfrac29$',correct:true},{text:'$\dfrac{32}{1}$',correct:false,why:'Multiplies the denominators and numerators instead of using the reciprocal.'},{text:'$\dfrac1{32}$',correct:false,why:'Inverts the entire result rather than multiplying by the reciprocal of $3/8$.'},{text:'$\dfrac92$',correct:false,why:'Uses the reciprocal operation in the wrong order and produces the reciprocal of the correct result.'}],solution_text:'Divide by a fraction by multiplying by its reciprocal: $\dfrac1{12}\div\dfrac38=\dfrac1{12}\times\dfrac83=\dfrac8{36}=\dfrac29$.',diagramRequired:false,uncertainties:[]}
  ,'83930': {question_text:'Which expression would correctly calculate the surface area of the base of the cone? The base diameter is $12.6\,\mathrm m$.',structure:'calculate-area-of-circular-cone-base-from-diameter',meaningfulCase:'convert-diameter-to-radius-before-circle-area',mastery:false,options:[{text:'$\dfrac{12.6\times4.2}{2}$',correct:false,why:'Uses the cone height and a triangle-style area formula rather than the circular base area.'},{text:'$\dfrac{\pi\times6.3\times4.2}{3}$',correct:false,why:'Uses the height and an incorrect factor instead of the radius-squared circle formula.'},{text:'$\pi\times6.3^2$',correct:true},{text:'None of these',correct:false,why:'The radius is half the diameter, so the listed circular-area expression is valid.'}],solution_text:'The radius is $12.6/2=6.3$ m. The area of the circular base is $\pi r^2=\pi\times6.3^2$.',diagramRequired:true,uncertainties:[]}
  ,'129112': {question_text:'A frequency table records the number of pets. In the highlighted row, the number of pets is 3 and the frequency is 2. How many pets did the people in the highlighted row have in total?',structure:'calculate-total-items-from-value-and-frequency',meaningfulCase:'multiply-number-per-person-by-number-of-people',mastery:false,options:[{text:'2',correct:false,why:'Gives the frequency only and does not count the pets across both people.'},{text:'3',correct:false,why:'Gives the number of pets per person rather than the total for the row.'},{text:'5',correct:false,why:'Adds the value and frequency instead of multiplying them.'},{text:'6',correct:true}],solution_text:'The highlighted row represents 2 people with 3 pets each. The total is $3\times2=6$ pets.',diagramRequired:true,uncertainties:[]}
  ,'98003': {question_text:'Tom and Katie are arguing about midpoints. M is the midpoint between P and Q. Tom says knowing M only gives more than one possible location for P and Q. Katie says knowing M and Q gives more than one possible location for P. Who is correct?',structure:'reason-about-uniqueness-of-midpoint-endpoints',meaningfulCase:'midpoint-equation-determines-missing-endpoint',mastery:false,options:[{text:'Only Tom',correct:true},{text:'Only Katie',correct:false,why:'Once M and Q are known, the midpoint equation gives the unique point $P=2M-Q$.'},{text:'Both Tom and Katie',correct:false,why:'Katie is incorrect because the missing endpoint is uniquely determined by the midpoint and the known endpoint.'},{text:'Neither is correct',correct:false,why:'Tom is correct: a midpoint alone does not determine the two endpoints uniquely.'}],solution_text:'A midpoint alone allows infinitely many pairs of endpoints symmetric about M. If M and Q are known, $M=(P+Q)/2$ determines $P=2M-Q$ uniquely. Thus only Tom is correct.',diagramRequired:false,uncertainties:[]}
  ,'13704': {question_text:'Factorise $x^2-25$.',structure:'factorise-difference-of-two-squares',meaningfulCase:'difference-of-squares-with-constant-square',mastery:false,options:[{text:'$(x+25)(x-1)$',correct:false,why:'The factors multiply to a different constant and do not represent a difference of squares.'},{text:'$(x+25)(x-25)$',correct:false,why:'Uses 25 rather than its square root 5 in the difference-of-squares factors.'},{text:'$(x-5)(x-5)$',correct:false,why:'Squares the same factor and produces a middle term $-10x$.'},{text:'$(x+5)(x-5)$',correct:true}],solution_text:'Since $25=5^2$, use $a^2-b^2=(a+b)(a-b)$ to obtain $x^2-25=(x+5)(x-5)$.',diagramRequired:false,uncertainties:[]}
  ,'28582': {question_text:'A counter is taken from a bag containing 4 red and 5 blue counters, replaced, and then another is picked. What is the probability of picking one red and one blue counter?',structure:'calculate-probability-of-one-of-each-with-replacement',meaningfulCase:'add-two-orders-for-red-blue-outcomes',mastery:false,options:[{text:'$\dfrac{40}{200}$',correct:false,why:'Uses only one order or fails to combine the two possible red-blue orders.'},{text:'$\dfrac{20}{100}$',correct:false,why:'Calculates the probability of one particular order only.'},{text:'$\dfrac9{10}$',correct:false,why:'Adds the red and blue probabilities instead of multiplying independent draws.'},{text:'$\dfrac{40}{100}$',correct:true}],solution_text:'The two valid orders are red then blue and blue then red. Their probabilities are $\frac4{10}\frac5{10}$ and $\frac5{10}\frac4{10}$, so the total is $\frac{40}{100}$.',diagramRequired:true,uncertainties:[]}
  ,'82763': {question_text:'This is a table of values for the line $y=5x-3$. When $x=-1$, what should replace the star?',structure:'evaluate-linear-rule-from-table',meaningfulCase:'substitute-negative-input-into-linear-equation',mastery:false,options:[{text:'$-7$',correct:false,why:'Uses the constant from a different linear rule and does not evaluate $5(-1)-3$.'},{text:'$2$',correct:false,why:'Copies the value at $x=1$ rather than calculating the value at $x=-1$.'},{text:'$-2$',correct:false,why:'Subtracts the coefficient incorrectly and does not multiply 5 by -1.'},{text:'$-8$',correct:true}],solution_text:'For $x=-1$, $y=5(-1)-3=-5-3=-8$.',diagramRequired:true,uncertainties:[]}
  ,'8673': {question_text:'Which two shapes are congruent?',structure:'identify-congruent-rectangles-on-grid',meaningfulCase:'same-side-lengths-independent-of-orientation',mastery:false,options:[{text:'C and B',correct:false,why:'The rectangles have different dimensions: C is longer than B.'},{text:'F and G',correct:true},{text:'F and B',correct:false,why:'F is a 2-by-4 rectangle whereas B is a 1-by-2 rectangle.'},{text:'A and E',correct:false,why:'A and E have different side lengths, even though both are rectangles.'}],solution_text:'Counting grid squares shows that F and G each measure 2 by 4 squares. A rotation or translation preserves these dimensions, so F and G are congruent.',diagramRequired:true,uncertainties:[]}
  ,'20124': {question_text:'Calculate the discriminant of the quadratic equation $2x^2+4x+5=0$.',structure:'calculate-quadratic-discriminant',meaningfulCase:'apply-b-squared-minus-four-ac',mastery:false,options:[{text:'$-32$',correct:false,why:'Uses an incorrect product for the $4ac$ term.'},{text:'$-24$',correct:true},{text:'$48$',correct:false,why:'Multiplies terms without subtracting $4ac$ from $b^2$.'},{text:'$56$',correct:false,why:'Adds the two discriminant components instead of subtracting them.'}],solution_text:'For $a=2$, $b=4$, $c=5$, the discriminant is $b^2-4ac=4^2-4(2)(5)=16-40=-24$.',diagramRequired:false,uncertainties:[]}
  ,'83738': {question_text:'M is the midpoint of Y and Z. Given the vectors shown by $\mathbf a$ and $\mathbf b$, write the vector $\overrightarrow{MY}$ in terms of $\mathbf a$ and $\mathbf b$.',structure:'find-midpoint-vector-from-two-directed-vectors',meaningfulCase:'half-difference-of-position-vectors-from-common-origin',mastery:false,options:[{text:'$\dfrac12(\mathbf b-\mathbf a)$',correct:false,why:'Reverses the endpoint difference and gives the vector from Y toward Z.'},{text:'$\dfrac12(\mathbf a+\mathbf b)$',correct:false,why:'Adds the two side vectors instead of forming the displacement from Z to Y.'},{text:'$\dfrac12(\mathbf a-\mathbf b)$',correct:true},{text:'$\dfrac12(-\mathbf a-\mathbf b)$',correct:false,why:'Reverses both vectors and points in the opposite direction to $\overrightarrow{MY}$.'}],solution_text:'With X as the common point, $\overrightarrow{XY}=\mathbf a$ and $\overrightarrow{XZ}=\mathbf b$. Thus $\overrightarrow{ZY}=\mathbf a-\mathbf b$. Since M is the midpoint, $\overrightarrow{MY}=\frac12\overrightarrow{ZY}=\frac12(\mathbf a-\mathbf b)$.',diagramRequired:true,uncertainties:['The source states the diagram is not accurately drawn; the vector directions are interpreted from the arrowheads.']}
  ,'20479': {question_text:'The diagram shows a circle of radius 4 cm with centre P. Which statement describes the shaded region?',structure:'describe-intersection-of-circle-and-half-planes',meaningfulCase:'inside-circle-left-of-vertical-and-below-horizontal-diameters',mastery:false,options:[{text:'Less than 4 cm from P, closer to S than T, closer to X than Y',correct:false,why:'The shaded region is below the horizontal diameter, so it is closer to Y than X.'},{text:'Less than 4 cm from P, closer to T than S, closer to Y than X',correct:false,why:'The shaded region lies on the S side of the vertical diameter, not closer to T.'},{text:'Less than 4 cm from P, closer to S than T, closer to Y than X',correct:true},{text:'More than 4 cm from P, closer to S than T, closer to Y than X',correct:false,why:'The shaded region lies inside the circle, so its distance from P is less than 4 cm.'}],solution_text:'The shaded region is inside the circle, below the horizontal diameter and to the left of the vertical diameter. Hence it is less than 4 cm from P, closer to S than T, and closer to Y than X.',diagramRequired:true,uncertainties:[]}
  ,'176206': {question_text:'I think of a number $a$. I divide my number by 11. I get 6. Which equation represents this?',structure:'translate-division-statement-into-equation',meaningfulCase:'unknown-divided-by-constant-equals-result',mastery:false,options:[{text:'$\dfrac a{11}=6$',correct:true},{text:'$a-11=6$',correct:false,why:'Represents subtraction by 11 rather than division by 11.'},{text:'$\dfrac{11}{6}=a$',correct:false,why:'Inverts the division and does not state that the unknown is divided by 11.'},{text:'$\dfrac{11}{a}=6$',correct:false,why:'Places the unknown in the denominator, reversing the stated operation.'}],solution_text:'Dividing the number $a$ by 11 and obtaining 6 is written $a/11=6$.',diagramRequired:false,uncertainties:[]}
  ,'177437': {question_text:'If $c=9$ and $d=5$, what is the value of $2c-d$?',structure:'evaluate-linear-expression-from-variable-values',meaningfulCase:'substitute-values-and-follow-order-of-operations',mastery:false,options:[{text:'13',correct:true},{text:'2',correct:false,why:'Uses only the difference between the given values instead of doubling $c$ first.'},{text:'24',correct:false,why:'Multiplies $c$ and $d$ rather than evaluating $2c-d$.'},{text:'18',correct:false,why:'Calculates $2c$ but fails to subtract the value of $d$.'}],solution_text:'Substitute $c=9$ and $d=5$: $2c-d=2(9)-5=18-5=13$.',diagramRequired:false,uncertainties:[]}
  ,'137606': {question_text:'If the polynomial $y=(x+a)(x+b)$ has only one zero, what is true about $a$ and $b$?',structure:'infer-repeated-root-from-factorised-quadratic',meaningfulCase:'one-zero-quadratic-has-equal-linear-factors',mastery:false,options:[{text:'$a$ and $b$ are the same',correct:true},{text:'$a$ and $b$ are opposites',correct:false,why:'Opposite values generally give two distinct zeros unless both are zero.'},{text:'$a$ and $b$ are reciprocals',correct:false,why:'Reciprocal constants do not force the two factors to have the same root.'},{text:'I’d just be guessing',correct:false,why:'A quadratic has one zero here only when the two factor roots coincide, so the relationship is determined.'}],solution_text:'The zeros are $x=-a$ and $x=-b$. Having only one zero means these coincide, so $a=b$.',diagramRequired:true,uncertainties:[]}
  ,'137613': {question_text:'One factor of $f(x)=x^3+4x^2+x-6$ is $x+2$. Use division to determine the other two factors.',structure:'factorise-cubic-using-given-linear-factor',meaningfulCase:'polynomial-division-followed-by-quadratic-factorisation',mastery:false,options:[{text:'$(x+1)$ and $(x+3)$',correct:false,why:'Their product with $x+2$ gives the wrong coefficient of $x$.'},{text:'$(x-1)$ and $(x+3)$',correct:true},{text:'$(x-1)$ and $(x-3)$',correct:false,why:'The resulting constant term has the wrong sign and magnitude.'},{text:'$(x+1)$ and $(x-3)$',correct:false,why:'These factors produce a different quadratic quotient and do not reconstruct the cubic.'}],solution_text:'Dividing by $x+2$ gives $x^2+2x-3$. This factorises as $(x-1)(x+3)$, so the other factors are $x-1$ and $x+3$.',diagramRequired:false,uncertainties:[]}
  ,'20178': {question_text:'A sequence is generated by $u_{n+1}=0.7u_n+10$. What is the limit of this sequence as $n\to\infty$?',structure:'find-limit-of-linear-recurrence',meaningfulCase:'fixed-point-equation-for-convergent-recurrence',mastery:false,options:[{text:'$\dfrac{100}{3}$',correct:true},{text:'$\dfrac{100}{7}$',correct:false,why:'Divides 100 by 7 instead of solving the fixed-point equation $L=0.7L+10$.'},{text:'$\dfrac{17}{100}$',correct:false,why:'Combines the recurrence coefficients as a fraction rather than finding the limiting value.'},{text:'$\dfrac3{10}$',correct:false,why:'Uses the coefficient 0.7 or its complement rather than the recurrence fixed point.'}],solution_text:'Let the limit be $L$. Then $L=0.7L+10$, so $0.3L=10$ and $L=10/0.3=100/3$.',diagramRequired:false,uncertainties:[]}
  ,'68266': {question_text:'Find the equation of the curve when $\dfrac{dy}{dx}=3x^2-6$ and the curve passes through $(1,4)$.',structure:'integrate-gradient-function-and-use-point-condition',meaningfulCase:'antidifferentiate-polynomial-and-determine-constant',mastery:false,options:[{text:'$y=\dfrac32x^3-6x-9$',correct:false,why:'Differentiates to $\frac92x^2-6$, not the stated derivative.'},{text:'$y=\dfrac23x^3+6x-9$',correct:false,why:'Uses an incorrect antiderivative coefficient and the wrong sign on the linear term.'},{text:'$y=x^3-6x+9$',correct:true},{text:'$y=x^3-6x-1$',correct:false,why:'Has the correct derivative but fails the condition $y(1)=4$.'}],solution_text:'Integrating gives $y=x^3-6x+C$. Substituting $(1,4)$ gives $4=1-6+C$, so $C=9$. Hence $y=x^3-6x+9$.',diagramRequired:false,uncertainties:[]}
  ,'87697': {question_text:'The diagram shows the graph of the derivative of a function $f$. Which one of $f_1(x)=x^2-4x$, $f_2(x)=x^2+4$, $f_3(x)=-x^2+4x-4$, and $f_4(x)=-x^2+4$ is $f$?',structure:'identify-function-from-graph-of-derivative',meaningfulCase:'match-linear-derivative-gradient-and-intercept',mastery:false,options:[{text:'$f_1(x)$',correct:false,why:'Its derivative $2x-4$ has positive slope, unlike the decreasing graph shown.'},{text:'$f_2(x)$',correct:false,why:'Its derivative $2x$ also has positive slope and passes through the origin.'},{text:'$f_3(x)$',correct:true},{text:'$f_4(x)$',correct:false,why:'Its derivative $-2x$ passes through the origin rather than having the shown positive intercept.'}],solution_text:'The derivative of $f_3(x)=-x^2+4x-4$ is $-2x+4$, a decreasing line with positive y-intercept and positive x-intercept, matching the graph.',diagramRequired:true,uncertainties:[]}
  ,'2222': {question_text:'Convert the mixed number $2\dfrac27$ to an improper fraction.',structure:'convert-mixed-number-to-improper-fraction',meaningfulCase:'multiply-whole-part-by-denominator-and-add-numerator',mastery:false,options:[{text:'$\dfrac{14}{7}$',correct:false,why:'Converts only the whole-number part and omits the extra numerator.'},{text:'$\dfrac{16}{7}$',correct:true},{text:'$\dfrac{16}{14}$',correct:false,why:'Changes the denominator incorrectly while forming the improper fraction.'},{text:'$\dfrac47$',correct:false,why:'Uses only the fractional numerator and ignores the whole-number part.'}],solution_text:'$2\frac27=\frac{2\times7+2}{7}=\frac{16}{7}$.',diagramRequired:false,uncertainties:[]}
  ,'41081': {question_text:'What does $\sqrt{300}$ simplify to?',structure:'simplify-surds-by-extracting-square-factor',meaningfulCase:'factor-perfect-square-from-radicand',mastery:false,options:[{text:'$\sqrt{10}\sqrt{30}$',correct:false,why:'Splits the radicand without extracting the largest perfect-square factor.'},{text:'$3\sqrt{10}$',correct:false,why:'Uses 9 rather than the factor 100 when simplifying 300.'},{text:'$10\sqrt3$',correct:true},{text:'$\sqrt3\sqrt{10}$',correct:false,why:'Leaves the product of square roots unsimplified and is not the standard simplified form.'}],solution_text:'Since $300=100\times3$, $\sqrt{300}=\sqrt{100}\sqrt3=10\sqrt3$.',diagramRequired:false,uncertainties:[]}
  ,'78602': {question_text:'Which of the following shapes is not being split into two congruent halves?',structure:'identify-noncongruent-bisection-of-shape',meaningfulCase:'compare-reflected-halves-created-by-dashed-cut',mastery:false,options:[{text:'A',correct:false,why:'The symmetry line of the isosceles triangle creates two matching triangular halves.'},{text:'B',correct:false,why:'The cut is positioned to produce two congruent trapezoidal parts.'},{text:'C',correct:false,why:'A suitable straight cut through the parallelogram produces two congruent parallelogram-like halves.'},{text:'D',correct:true}],solution_text:'The dashed L-shaped cut in D does not produce two matching halves under a rigid motion, unlike the symmetric cuts in the other shapes. Therefore D is not split into congruent halves.',diagramRequired:true,uncertainties:['The source diagram is labelled not to scale, so the conclusion follows from the intended cut construction and symmetry.']}
  ,'101953': {question_text:'An antiderivative of $\dfrac1{9+4x^2}$ is...',structure:'integrate-reciprocal-quadratic-to-arctangent',meaningfulCase:'match-scaled-arctangent-integral-formula',mastery:false,options:[{text:'$\dfrac19\tan^{-1}\left(\dfrac{2x}{9}\right)$',correct:false,why:'Uses the wrong prefactor and the wrong arctangent scale.'},{text:'$\dfrac13\tan^{-1}\left(\dfrac{2x}{3}\right)$',correct:false,why:'Has the correct arctangent argument but an excessive prefactor.'},{text:'$\dfrac16\tan^{-1}\left(\dfrac{2x}{3}\right)$',correct:true},{text:'$9\tan^{-1}\left(\dfrac{2x}{9}\right)$',correct:false,why:'Reverses the required scale factor and does not differentiate to the integrand.'}],solution_text:'Use $\int\frac{dx}{a^2+u^2}=\frac1a\tan^{-1}(u/a)$. Writing $9+4x^2=3^2+(2x)^2$ gives $\frac16\tan^{-1}(2x/3)$.',diagramRequired:false,uncertainties:[]}
  ,'104128': {question_text:'Evaluate $\displaystyle\int_0^{\pi/2}\sin^5(x)\,dx$.',structure:'evaluate-definite-integral-of-odd-sine-power',meaningfulCase:'reduction-of-sine-power-on-quarter-period',mastery:false,options:[{text:'$\dfrac8{15}$',correct:true},{text:'$\dfrac87$',correct:false,why:'Uses an incorrect reduction value for the fifth power integral.'},{text:'$\dfrac4{15}$',correct:false,why:'Is half of the correct quarter-period integral.'},{text:'$\dfrac17$',correct:false,why:'Confuses the reciprocal reduction factor with the value of the integral.'}],solution_text:'Using the standard reduction integral, $\int_0^{\pi/2}\sin^5x\,dx=\frac45\cdot\frac23=\frac8{15}$.',diagramRequired:false,uncertainties:[]}
  ,'120607': {question_text:'Make $y$ the subject of $x=e^{3y-2}$.',structure:'rearrange-exponential-equation-using-logarithms',meaningfulCase:'take-natural-log-and-isolate-variable',mastery:false,options:[{text:'$y=\dfrac13(2+\ln x)$',correct:true},{text:'$y=\dfrac13\ln(x+e^2)$',correct:false,why:'Adds $e^2$ inside the logarithm instead of taking the logarithm of the whole exponential equation.'},{text:'$y=\dfrac13\ln(2x)$',correct:false,why:'Uses multiplication by 2 rather than adding 2 after taking the natural logarithm.'},{text:'$y=\ln\left(\dfrac{x+2}{3}\right)$',correct:false,why:'Divides and combines terms inside the logarithm incorrectly.'}],solution_text:'Take logs: $\ln x=3y-2$. Therefore $3y=\ln x+2$, so $y=\frac13(2+\ln x)$.',diagramRequired:false,uncertainties:[]}
  ,'83979': {question_text:'100 students had homework. 46 were boys, 15 did not do their homework, and 51 girls did their homework. What number should replace the star for boys who did their homework?',structure:'complete-frequency-tree-from-marginal-and-joint-frequencies',meaningfulCase:'total-homework-minus-girls-homework',mastery:false,options:[{text:'34',correct:true},{text:'3',correct:false,why:'Does not use the total number who did homework and is not the required boys-homework frequency.'},{text:'12',correct:false,why:'Subtracts the wrong marginal frequencies and does not account for all 100 students.'},{text:'23',correct:false,why:'Uses an unrelated difference rather than calculating total homework minus girls homework.'}],solution_text:'Of the 100 students, 15 did not do homework, so 85 did. Of these, 51 were girls, leaving $85-51=34$ boys who did homework.',diagramRequired:true,uncertainties:[]}
  ,'95482': {question_text:'In the diagram, two exterior angles are $126^\circ$ and $115^\circ$. What is the size of angle $p$?',structure:'find-triangle-angle-from-exterior-angles',meaningfulCase:'convert-exterior-to-interior-and-use-angle-sum',mastery:false,options:[{text:'$54^\circ$',correct:false,why:'Uses the left interior angle only and does not subtract both known angles from 180 degrees.'},{text:'$61^\circ$',correct:true},{text:'$65^\circ$',correct:false,why:'Uses the right interior angle as the unknown rather than finding the third angle.'},{text:'Not enough information',correct:false,why:'The two exterior angles determine the other two interior angles and hence determine p.'}],solution_text:'The two known interior angles are $180-126=54^\circ$ and $180-115=65^\circ$. Thus $p=180-54-65=61^\circ$.',diagramRequired:true,uncertainties:[]}
  ,'135968': {question_text:'Without using a calculator, what is the exact value of $\sin30^\circ$?',structure:'recall-exact-trigonometric-value',meaningfulCase:'special-angle-sine-value',mastery:false,options:[{text:'$0.5$',correct:true},{text:'$0.30$',correct:false,why:'Confuses the angle in degrees with its sine value.'},{text:'$\dfrac{\sqrt3}{2}$',correct:false,why:'This is the exact value of $\sin60^\circ$, not $\sin30^\circ$.'},{text:'$\dfrac{\sqrt3}{3}$',correct:false,why:'This value is associated with a tangent or reciprocal relationship, not sine of 30 degrees.'}],solution_text:'The standard exact value is $\sin30^\circ=\frac12=0.5$.',diagramRequired:false,uncertainties:[]}
  ,'129924': {question_text:'Differentiate $\sin\left(\dfrac x2\right)$.',structure:'differentiate-sine-of-linear-function',meaningfulCase:'chain-rule-with-inner-derivative-one-half',mastery:false,options:[{text:'$-\cos\left(\dfrac x2\right)$',correct:false,why:'Uses the wrong sign for the derivative of sine.'},{text:'$-\dfrac12\cos\left(\dfrac x2\right)$',correct:false,why:'Uses the chain-rule factor but introduces an incorrect negative sign.'},{text:'$\cos\left(\dfrac x2\right)$',correct:false,why:'Omits the inner derivative of $x/2$.'},{text:'$\dfrac12\cos\left(\dfrac x2\right)$',correct:true}],solution_text:'By the chain rule, $\frac d{dx}\sin(x/2)=\cos(x/2)\cdot\frac12=\frac12\cos(x/2)$.',diagramRequired:false,uncertainties:[]}
  ,'8671': {question_text:'Which two shapes are congruent?',structure:'identify-congruent-shapes-under-rotation',meaningfulCase:'same-size-and-shape-l-shaped-polygons',mastery:false,options:[{text:'H and L',correct:true},{text:'J and E',correct:false,why:'The star shapes have different arm shapes and are not congruent.'},{text:'I and K',correct:false,why:'The circles have different sizes.'},{text:'B and F',correct:false,why:'The triangular shapes have different side proportions.'}],solution_text:'Shapes H and L have the same dimensions and arrangement of the right-angled parts; one can be rotated to match the other. Therefore H and L are congruent.',diagramRequired:true,uncertainties:[]}
  ,'122059': {question_text:'Given $y=\\dfrac{3\\sin\\theta}{2\\sin\\theta+2\\cos\\theta}$, where $-\\dfrac\\pi4<\\theta<\\dfrac{3\\pi}4$, show that $\\dfrac{dy}{d\\theta}=\\dfrac{A}{1+\\sin2\\theta}$. Find $A$.',structure:'differentiate-trigonometric-quotient-and-identify-constant',meaningfulCase:'quotient-rule-with-sine-cosine-denominator',mastery:false,options:[{text:'$\\dfrac32$',correct:true},{text:'$\\dfrac52$',correct:false,why:'Adds the coefficients instead of simplifying the quotient-rule numerator.'},{text:'$\\dfrac54$',correct:false,why:'Uses an incorrect factor when converting $(\\sin\\theta+\\cos\\theta)^2$.'},{text:'$\\dfrac29$',correct:false,why:'Inverts and rescales the constant incorrectly after differentiation.'}],solution_text:'The quotient rule gives $\\dfrac{dy}{d\\theta}=\\dfrac{3}{2(\\sin\\theta+\\cos\\theta)^2}$. Since $(\\sin\\theta+\\cos\\theta)^2=1+\\sin2\\theta$, $A=\\dfrac32$.',diagramRequired:false,uncertainties:[]}
  ,'149608': {question_text:'The horizontal and vertical components of the velocity of a projectile are respectively $v_x$ and $v_y$. Which pair of graphs best represents the velocity of the projectile?',structure:'identify-projectile-horizontal-and-vertical-velocity-graphs',meaningfulCase:'horizontal-velocity-constant-and-vertical-velocity-linear',mastery:false,options:[{text:'A',correct:false,why:'Shows both velocity components constant, ignoring the effect of gravity on the vertical component.'},{text:'B',correct:true},{text:'C',correct:false,why:'Shows the horizontal component changing while the vertical component stays constant.'},{text:'D',correct:false,why:'Shows curved velocity components rather than constant horizontal and uniformly changing vertical velocity.'}],solution_text:'Ignoring air resistance, horizontal acceleration is zero, so $v_x$ is constant. Vertical acceleration is constant and downward, so $v_y$ decreases linearly with time. Graph B has these features.',diagramRequired:true,uncertainties:[]}
  ,'119552': {question_text:'Which inequality is represented by the shaded region?',structure:'read-quadratic-inequality-from-shaded-interval',meaningfulCase:'between-roots-of-upward-opening-quadratic',mastery:false,options:[{text:'$x^2+x-5\\leq0$',correct:false,why:'Includes the boundary roots, but the dashed boundary lines indicate that the roots are excluded.'},{text:'$x^2+x-5\\geq0$',correct:false,why:'Represents the outside regions of the upward-opening parabola, not the shaded interval between roots.'},{text:'$x^2+x-5<0$',correct:true},{text:'$x^2+x-5>0$',correct:false,why:'Represents values outside the roots and would shade the two outer intervals.'}],solution_text:'The shaded strip lies between the two roots of $x^2+x-5=0$, where the upward-opening quadratic is negative. The dashed boundaries exclude the roots, so the inequality is $x^2+x-5<0$.',diagramRequired:true,uncertainties:[]}
  ,'135647': {question_text:'Simplify $\\sqrt{1-\\sin^2(\\theta)}$.',structure:'simplify-square-root-of-pythagorean-identity',meaningfulCase:'principal-square-root-gives-absolute-cosine',mastery:false,options:[{text:'$\\sqrt{\\cos\\theta}$',correct:false,why:'Applies the identity incorrectly by leaving a square root on the cosine.'},{text:'$\\cos^2\\theta$',correct:false,why:'Removes the square root without taking the required absolute value or square-root result.'},{text:'$\\cos\\theta$',correct:false,why:'Ignores that the principal square root of $\\cos^2\\theta$ is $|\\cos\\theta|$.'},{text:'None of the above',correct:true}],solution_text:'Using $1-\\sin^2\\theta=\\cos^2\\theta$, we get $\\sqrt{1-\\sin^2\\theta}=\\sqrt{\\cos^2\\theta}=|\\cos\\theta|$. Since $|\\cos\\theta|$ is not listed, the answer is none of the above.',diagramRequired:false,uncertainties:['The source does not state a restricted interval for $\\theta$, so $\\cos\\theta$ cannot generally replace $|\\cos\\theta|$.']}
  ,'84327': {question_text:'Which of these does not describe the direction of the displayed vector?',structure:'compare-vector-direction-angle-descriptions',meaningfulCase:'equivalent-clockwise-and-anticlockwise-direction-angles',mastery:false,options:[{text:'$210^\\circ$ anticlockwise from the positive $j$-direction',correct:true},{text:'$120^\\circ$ clockwise from the positive $j$-direction',correct:false,why:'This is equivalent to a direction 30 degrees below the positive i-axis.'},{text:'$330^\\circ$ anticlockwise from the positive $i$-direction',correct:false,why:'This is the standard anticlockwise angle for a vector 30 degrees below the positive i-axis.'},{text:'$30^\\circ$ clockwise from the positive $i$-direction',correct:false,why:'This directly describes the displayed vector below the positive i-axis.'}],solution_text:'The vector is 30 degrees clockwise from the positive $i$-direction, equivalently 330 degrees anticlockwise from $i$, or 120 degrees clockwise from the positive $j$-direction. The description 210 degrees anticlockwise from $j$ points in a different direction.',diagramRequired:true,uncertainties:[]}
};

const authoritative = JSON.parse(fs.readFileSync(inputPath, 'utf8'));
const assigned = authoritative.jobs.filter(job => { const n=Number(job.jobId.replace(/^dq-visual-/,'')); return ((n-1)%10)+1===9; });
fs.mkdirSync(outputDir,{recursive:true});
for (const job of assigned) {
  const outPath=path.join(outputDir,`${job.jobId}.json`);
  if (fs.existsSync(outPath)) { try { const old=JSON.parse(fs.readFileSync(outPath,'utf8')); const hasFallback=old.candidates?.some(c=>c.transcription?.question_text?.startsWith('[Uncertain source ')); if(old.jobId===job.jobId && old.candidates?.length===job.candidates.length && old.candidates.every(c=>c.transcription) && !hasFallback) continue; } catch {} }
  const candidates=job.candidates.map(candidate=>{
    if(candidate.transcription) return {...candidate};
    if(t[candidate.source.id]) return {...candidate,transcription:t[candidate.source.id]};
    return {...candidate,transcription:{
      question_text:`[Uncertain source ${candidate.source.id}: manual visual transcription required.]`,
      structure:'uncertain-source-transcription',
      meaningfulCase:'source-content-not-fully-transcribed',
      mastery:false,
      options:[
        {text:'Source option A',correct:true},
        {text:'Source option B',correct:false,why:'Source option text requires manual visual transcription.'},
        {text:'Source option C',correct:false,why:'Source option text requires manual visual transcription.'},
        {text:'Source option D',correct:false,why:'Source option text requires manual visual transcription.'}
      ],
      solution_text:'The source image requires manual visual transcription and independent solving before a reliable solution can be recorded.',
      diagramRequired:true,
      uncertainties:[`Source ${candidate.source.id} was not fully transcribed; manual review is required.`]
    }};
  });
  fs.writeFileSync(outPath,JSON.stringify({jobId:job.jobId,candidates},null,2)+'\n','utf8');
}
